import { actors, guidedLesson } from './lesson-kit';
import type { Check, Lesson } from './types';
import type { LessonDiagramSpec } from './lesson-diagrams';

// French explanations are constructed teaching material. A2 and L2/L5/L6 numbers are
// recalculations from the dossier, not an official marking scheme. Every new exam below
// is explicitly a constructed training question. No externality graph is reused here.
const choice = (id: string, q: string, right: string, yes: string, wrong: [string, string][], dim: 'intuition' | 'terminology' | 'formula' | 'graph' | 'recognition' | 'english' = 'intuition'): Check => ({
  kind: 'choice', id, q, dim, tags: [], options: [
    ...wrong.slice(0, 1).map(([text, feedback]) => ({ text, feedback })),
    { text: right, correct: true, feedback: yes },
    ...wrong.slice(1).map(([text, feedback]) => ({ text, feedback })),
  ],
});
const num = (id: string, q: string, answer: number, explain: string, unit = '', traps?: { value: number; feedback: string }[]): Check => ({ kind: 'numeric', id, q, answer, explain, unit, dim: 'calculation', tags: [], tol: 0.015, traps });

const sdGraph: LessonDiagramSpec = {
  kind: 'curves', title: 'Le prix coordonne deux décisions', xLabel: 'Q, unités par semaine', yLabel: 'p, € par unité', xMax: 10, yMax: 12,
  refs: ['3'], note: 'Exemple L2 du dossier. Demande inverse p = 10 − Q ; offre inverse p = 2 + Q. Les segments représentent exactement ces fonctions sur les quantités non négatives.',
  curves: [
    { label: 'Demande : p = 10 − Q', color: 'buyer', points: [[0, 10], [10, 0]], explain: 'Hauteur = prix maximal auquel cette unité est demandée.' },
    { label: 'Offre : p = 2 + Q', color: 'producer', points: [[0, 2], [10, 12]], explain: 'Hauteur = prix minimal pour que cette unité soit offerte.' },
  ], markers: [{ x: 4, y: 6, label: 'Équilibre : Q = 4, p = 6' }], initial: 4,
};
const demandShiftGraph: LessonDiagramSpec = {
  ...sdGraph, title: 'Plus de demande à chaque prix', yMax: 14,
  note: 'Choc construit : QD passe de 10 − p à 14 − p. Offre inchangée QS = p − 2. L’ancien prix 6 crée une pénurie ; le nouveau point est (6, 8).',
  curves: [sdGraph.curves[0], { label: 'Nouvelle demande : p = 14 − Q', color: 'third', points: [[0, 14], [10, 4]], explain: 'À p = 6, les acheteurs veulent 8 unités au lieu de 4.' }, sdGraph.curves[1]],
  markers: [{ x: 4, y: 6, label: 'Ancien équilibre' }, { x: 6, y: 8, label: 'Nouveau : Q = 6, p = 8' }], initial: 6,
};
const supplyShiftGraph: LessonDiagramSpec = {
  ...sdGraph, title: 'L’input coûte 2 € de plus par unité', yMax: 14,
  note: 'Choc construit : l’offre inverse passe de 2 + Q à 4 + Q, demande inchangée. Le point d’équilibre devient Q = 3, p = 7.',
  curves: [sdGraph.curves[0], sdGraph.curves[1], { label: 'Nouvelle offre : p = 4 + Q', color: 'third', points: [[0, 4], [10, 14]], explain: 'Pour une même quantité, il faut un prix supérieur de 2 €.' }],
  markers: [{ x: 4, y: 6, label: 'Ancien' }, { x: 3, y: 7, label: 'Nouveau : Q = 3, p = 7' }], initial: 3,
};

const SD = guidedLesson({
  id: 'sd-guided', topic: 'sd', node: 'sd', title: 'Offre et demande — le marché du café', mechanism: 'Deux décisions, un prix, puis un choc',
  teaser: 'Le café manque à 4 € et reste sur le comptoir à 8 €. Tu vas comprendre pourquoi, construire le prix qui coordonne tout le monde, puis déplacer les bonnes courbes.',
  actors: actors({ buyer: ['Les étudiants', 'achètent des cafés chaque semaine', 'une boisson qui vaut au moins ce qu’elle coûte'], producer: ['Les cafés du campus', 'vendent une boisson homogène', 'un prix qui couvre le coût de la boisson suivante'], planner: ['Toi, analyste', 'définis le marché et observes les décisions', 'expliquer prix et quantité sans confondre cause et réaction'] }),
  blocks: [
    { id: 'scene', title: 'Un prix affiché, deux décisions séparées', human: 'Imagine plusieurs cafés du campus vendant la même boisson cette semaine. Les étudiants décident combien acheter ; chaque vendeur décide combien préparer. Personne ne choisit à lui seul le prix de tout le marché : on travaille avec des agents price takers.', economist: 'Un marché est défini par un produit, une zone et une période. Le modèle concurrentiel simple suppose de nombreux agents et un produit homogène.', exam: 'A competitive market coordinates the decisions of price-taking buyers and sellers.', why: ['Un étudiant peut refuser un café, mais ne peut pas imposer un prix à tous les cafés.', 'Un vendeur affronte assez de concurrents pour prendre le prix de marché comme donné.', 'Définir le marché empêche de comparer une quantité quotidienne locale à une demande nationale annuelle.'], example: 'Dans l’exemple L2, QD = 10 − p et QS = p − 2 : p est en € par unité et Q en unités par semaine. À p = 6, chaque côté décide Q = 4.', me: 'Tu es étudiant : tu regardes le prix avant d’acheter. Tu es vendeur : tu regardes le même prix avant de préparer. Les deux plans peuvent être incompatibles.', diagram: sdGraph, refs: ['3'], provenance: 'doc', focusActors: ['buyer', 'producer'], checks: [choice('scene', 'Dans ce modèle, qui choisit la quantité demandée ?', 'Les acheteurs, au prix qu’ils observent', 'Oui. Le prix est donné pour chaque acheteur ; la demande décrit sa réaction.', [['Le vendeur choisit aussi les achats des étudiants', 'Il choisit l’offre, pas le désir d’achat des autres.'], ['L’analyste fixe directement Q = 4', 'Il calcule où les décisions se coordonnent ; il ne commande pas les achats.']])] },
    { id: 'buyer', title: 'Ce que veut dire une demande', human: 'À 4 €, davantage d’étudiants jugent le café intéressant qu’à 8 €. Certains renoncent à une autre boisson ; d’autres gardent leur argent. La demande décrit combien ils voudraient acheter à chaque prix, avec revenu, goûts et prix des autres biens maintenus constants.', economist: 'Demande directe QD(p) = 10 − p, sur son domaine positif ; demande inverse pD(Q) = 10 − Q.', exam: 'Quantity demanded decreases when the good’s own price rises, other determinants held constant.', why: ['Un prix plus élevé exclut les achats dont la valeur est trop faible.', 'On garde les autres déterminants constants pour isoler la réaction au prix du café.', 'La demande entière est une relation ; la quantité demandée est un point sur cette relation.'], example: 'À p = 4, QD = 6 ; à p = 8, QD = 2. On ne dit pas « la demande a diminué » si seul p change : on passe de 6 à 2 le long de la même courbe.', me: 'Tu aurais acheté deux cafés cette semaine à petit prix. Quand le prix monte, tu gardes seulement celui avant ton cours le plus long.', diagram: sdGraph, refs: ['3', '2.4'], provenance: 'peda', checks: [num('demand', 'Avec QD = 10 − p, combien les acheteurs souhaitent-ils acheter à p = 4 ?', 6, 'QD(4) = 10 − 4 = 6 unités par semaine.', 'unités'), choice('direct-inverse', 'Sur un graphique Q horizontal et p vertical, quelle fonction donne la hauteur de la demande ?', 'p = 10 − Q', 'Oui : la hauteur est un prix. La demande directe donne Q en fonction du prix.', [['Q = 10 − p doit être l’axe vertical', 'Q est horizontal ici ; réécris la même relation sous la forme p(Q).']], 'graph')] },
    { id: 'seller', title: 'Ce que voit celui qui prépare le café', human: 'Pour préparer davantage, les vendeurs mobilisent du temps, des grains et parfois une machine moins pratique. Ils ne veulent proposer une unité que si son prix couvre son coût supplémentaire. Dans ce modèle, les unités supplémentaires deviennent plus coûteuses.', economist: 'Offre directe QS = p − 2, soit l’offre inverse pS = 2 + Q. À prix donné, l’offre décrit les quantités que les producteurs souhaitent vendre.', exam: 'A higher price makes additional, more costly units worth supplying.', why: ['Les premiers cafés utilisent les ressources les plus faciles à mobiliser.', 'Produire davantage peut exiger des ressources plus coûteuses ; le prix doit compenser ce coût marginal.', 'Une hausse du prix du café accroît la quantité offerte le long de l’offre ; elle ne change pas les coûts de production eux-mêmes.'], example: 'À p = 4, QS = 2 ; à p = 8, QS = 6. Pour Q = 6, le prix minimal de l’offre est 2 + 6 = 8 €.', me: 'Tu tiens le café : à 4 € tu ne prépares pas les unités qui coûtent 7 €. À 8 €, ces unités deviennent possibles.', diagram: sdGraph, refs: ['3', '6.5'], provenance: 'peda', checks: [num('supply', 'Avec QS = p − 2, combien est offert à p = 8 ?', 6, 'QS(8) = 8 − 2 = 6.', 'unités'), choice('cost-side', 'Un prix de vente supérieur permet davantage d’offre parce que…', 'Des unités supplémentaires dont le coût était trop élevé deviennent rentables', 'Exact : compare le prix reçu au coût de l’unité suivante.', [['Le prix rend automatiquement les machines plus efficaces', 'Une nouvelle technologie déplacerait l’offre ; le prix seul ne change pas la technologie.']])] },
    { id: 'equilibrium', title: 'Gagne la formule : rendre les deux plans compatibles', human: 'À un prix donné, les acheteurs annoncent une quantité et les vendeurs une autre. Il faut un prix pour lequel ces deux plans portent sur le même nombre d’unités. Ce prix est l’équilibre : il n’y a ni acheteurs frustrés ni offre invendue dans ce modèle.', economist: 'Market equilibrium : QD(p*) = QS(p*). Égaliser les quantités souhaitées donne p*, puis remplacer dans une courbe donne Q*.', exam: 'Market equilibrium occurs where quantity demanded equals quantity supplied.', reveal: { q: 'Quelle égalité impose que les plans se rencontrent ?', options: [{ text: 'QD = QS', correct: true, feedback: 'Oui : les mêmes unités sont achetées et vendues.' }, { text: 'QD + QS = 0', feedback: 'Les quantités ne s’annulent pas ; elles doivent coïncider.' }, { text: 'p = 0', feedback: 'Un prix nul ne coordonne pas automatiquement les décisions.' }], formula: '10 − p = p − 2 ⇒ 12 = 2p ⇒ p* = 6 ; Q* = 10 − 6 = 4', tags: ['sd'] }, why: ['Si QD dépasse QS, des acheteurs voudraient acheter mais aucune unité ne leur est proposée.', 'Si QS dépasse QD, certaines unités prévues ne trouvent pas preneur.', 'L’égalité retire ces deux pressions ; c’est une condition de cohérence des décisions, pas un objectif choisi par une personne.'], example: 'À p = 6 : QD = 4 et QS = 4. Inversement, à Q = 4, pD = 6 et pS = 6. Les formes directe et inverse racontent le même point.', me: 'Tu proposes un prix ; demande à un étudiant et à un vendeur leurs quantités. Répète jusqu’à ce que les deux réponses coïncident.', diagram: sdGraph, refs: ['3'], provenance: 'recalc', result: ['Le point où les plans se coordonnent', 'p* = 6 ; Q* = 4'], checks: [num('pstar', 'Résous 10 − p = p − 2. Quel est p* ?', 6, '12 = 2p, donc p* = 6 €.', '€'), { kind: 'build', id: 'equation', dim: 'formula', tags: [], q: 'Reconstruis l’égalité d’équilibre en quantités.', lhs: 'Équilibre', tokens: ['10', '−', 'p', '=', 'p', '−', '2', '+'], accept: [['10', '−', 'p', '=', 'p', '−', '2']], explain: 'La quantité demandée 10 − p doit égaler la quantité offerte p − 2.' }] },
    { id: 'shortage', title: 'Pourquoi 4 € ne tient pas', human: 'Le café est affiché à 4 €. Six unités sont voulues mais seules deux sont proposées : quatre demandes restent insatisfaites. Les acheteurs prêts à payer davantage et les vendeurs voyant cette file créent une pression à la hausse sur le prix.', economist: 'Excess demand ou shortage : QD − QS > 0. Une pénurie se mesure en unités, pas en euros.', exam: 'At p = 4, excess demand is 6 − 2 = 4 units, creating upward pressure on price.', why: ['La file matérialise un écart entre deux plans au même prix.', 'Une hausse du prix réduit certains achats et rend d’autres unités rentables à produire.', 'Ces deux réactions referment l’écart jusqu’à QD = QS ; la pression décrit un ajustement, pas sa vitesse précise.'], example: 'À p = 4, pénurie = (10 − 4) − (4 − 2) = 6 − 2 = 4. À p = 5, elle n’est plus que 5 − 3 = 2.', me: 'Tu arrives après les deux cafés disponibles. Tu es prêt à payer plus que 4 €, mais le prix affiché empêchait encore cette adaptation.', diagram: sdGraph, refs: ['3'], provenance: 'recalc', checks: [num('shortage', 'Quelle est la pénurie à p = 4 ?', 4, 'QD = 6, QS = 2 : il manque 4 unités.', 'unités', [{ value: 2, feedback: '2 est la quantité offerte, pas le nombre d’achats qui restent insatisfaits.' }]), { kind: 'order', id: 'shortage-order', dim: 'intuition', tags: [], q: 'Remets l’ajustement dans l’ordre.', items: ['Au prix bas, QD dépasse QS', 'La pénurie crée une pression à la hausse du prix', 'La quantité demandée baisse et la quantité offerte monte', 'Les deux plans se rejoignent'] }] },
    { id: 'surplus', title: 'Pourquoi 8 € crée l’effet inverse', human: 'À 8 €, les vendeurs prévoient six unités, mais les acheteurs n’en veulent que deux. Quatre unités restent invendues. Un vendeur peut baisser le prix pour attirer un acheteur ; cette pression pousse vers l’équilibre.', economist: 'Excess supply ou surplus : QS − QD > 0. Ce surplus d’offre n’est pas le surplus monétaire du consommateur.', exam: 'At p = 8, excess supply creates downward pressure on price.', why: ['Une unité sans acheteur ne rapporte rien au vendeur.', 'Baisser le prix attire des achats supplémentaires et incite certains vendeurs à réduire leur offre.', 'Les réactions vont dans le même sens : refermer l’excès d’offre.'], example: 'À p = 8, QS − QD = 6 − 2 = 4. À p = 7, QS − QD = 5 − 3 = 2.', me: 'Tu as préparé des cafés que personne ne vient prendre à ce prix. Une remise peut valoir mieux que des invendus.', diagram: sdGraph, refs: ['3'], provenance: 'recalc', checks: [choice('surplus-direction', 'À p = 8, quelle pression apparaît ?', 'Une pression à la baisse du prix', 'Oui. QS = 6 dépasse QD = 2 ; des vendeurs cherchent des acheteurs.', [['Une pression à la hausse, car les vendeurs produisent beaucoup', 'Produire ne garantit pas vendre : les invendus incitent à baisser le prix.'], ['Aucune, car chaque vendeur choisit librement', 'Les choix sont libres mais ne sont pas compatibles à ce prix.']])] },
    { id: 'movement', title: 'La question qui évite de déplacer la mauvaise courbe', human: 'Tu observes que le prix du café a augmenté. Cela suffit pour lire moins d’achats le long d’une demande donnée ; cela ne prouve pas que les goûts ont changé. Avant de déplacer une courbe, cherche ce qui a changé en dehors du prix du bien représenté.', economist: 'Own-price change : movement along a curve. Change in another determinant : shift of the curve.', exam: 'A change in the good’s own price causes a movement along its demand curve, not a shift.', why: ['Une courbe contient déjà la réponse à tous les prix possibles.', 'Changer seulement le prix choisit un autre point de cette même relation.', 'Changer le revenu, le goût ou un prix lié modifie au contraire la quantité voulue à chaque prix.'], example: 'Prix du café 6 → 8, tout le reste fixé : QD 4 → 2 sur D. Revenu plus élevé pour un café normal : à p = 6 on pourrait vouloir 8 au lieu de 4 ; il faut une nouvelle D.', me: 'Pose-toi « à prix du café identique, voudrais-je plus de cafés ? ». Si oui, c’est un déplacement ; sinon tu regardes une réaction au prix.', diagram: sdGraph, refs: ['3'], provenance: 'peda', checks: [choice('movement', 'Le prix du café lui-même monte, sans autre changement. Que dessines-tu ?', 'Un mouvement le long de la demande', 'Le prix est une variable déjà représentée sur la courbe.', [['La demande se déplace à gauche', 'Il faudrait une baisse des goûts, du revenu pour un bien normal, ou un autre déterminant.'], ['La demande se déplace à droite', 'Un prix propre plus élevé ne crée pas plus de demande à prix donné.']], 'graph')] },
    { id: 'demand-shift', title: 'Une nouvelle promotion d’étudiants arrive', human: 'Plus d’étudiants veulent maintenant un café à chaque prix. À l’ancien prix de 6 €, les vendeurs proposent encore quatre unités mais les acheteurs en veulent huit. La pénurie fait monter le prix ; les vendeurs réagissent le long de leur offre inchangée.', economist: 'Un choc positif de demande déplace D à droite. Avec une offre croissante inchangée, p* et Q* augmentent.', exam: 'Higher demand raises the equilibrium price and quantity, holding supply constant.', why: ['Le nouveau groupe d’étudiants est une cause extérieure au prix du café.', 'À prix inchangé, la quantité demandée augmente : D se déplace, pas S.', 'Le prix plus élevé attire ensuite davantage de quantité offerte sur la même S.'], example: 'Choc construit : QD = 14 − p, QS = p − 2. 14 − p = p − 2 ⇒ p = 8 ; Q = 6. Par rapport à (4, 6), Q gagne 2 et p gagne 2.', me: 'Tu vends au campus : tes coûts n’ont pas changé. Tu peux néanmoins produire plus parce que de nouveaux acheteurs font monter le prix.', diagram: demandShiftGraph, refs: ['3'], provenance: 'peda', checks: [num('demand-shock-p', 'Avec QD = 14 − p et QS = p − 2, quel est le nouveau prix ?', 8, '16 = 2p ⇒ p = 8 ; chaque côté choisit 6 unités.', '€'), choice('s-not-shift', 'Pourquoi les vendeurs produisent-ils plus après ce choc ?', 'Ils répondent au prix plus élevé le long de leur offre', 'Exact. Le déterminant initial est du côté de la demande ; les coûts sont inchangés.', [['Leur offre s’est déplacée car ils vendent davantage', 'Une quantité offerte plus élevée ne signifie pas que la relation d’offre a changé.']])] },
    { id: 'related-goods', title: 'Thé, biscuits, revenu : retrouve le sens du choc', human: 'Le prix du thé augmente : certains étudiants basculent vers le café s’ils sont substituts. Le prix des biscuits augmente : si café et biscuits sont complémentaires, l’ensemble devient moins attirant. Le même mot « autre prix » peut donc déplacer la demande dans des sens opposés.', economist: 'Substitutes : une hausse du prix de l’autre bien accroît la demande. Complements : elle la réduit. Bien normal : une hausse du revenu accroît la demande ; bien inférieur : elle la réduit.', exam: 'A higher substitute price shifts demand right; a higher complement price shifts it left.', why: ['Pour des substituts, le café devient relativement plus intéressant que l’autre option.', 'Pour des compléments, acheter le duo devient plus cher ; les deux usages peuvent reculer.', 'Le revenu modifie les possibilités d’achat, mais le signe dépend du type de bien et non d’un jugement de qualité.'], example: 'Situation construite : à p_café = 6, QD passe de 4 à 6 après une hausse du prix du thé. Cela décrit un déplacement de demande de +2 à ce prix, pas une variation du prix du café.', me: 'Tu ne regardes pas seulement l’étiquette du café : tu compares les boissons possibles et ce que ton budget te permet.', refs: ['3', '4.5', '5'], provenance: 'peda', checks: [choice('complement', 'Si café et biscuits sont complémentaires, le prix des biscuits monte. Que devient D du café ?', 'Elle se déplace à gauche', 'Le duo est plus cher ; à prix du café donné, moins de café est demandé.', [['Elle se déplace à droite comme pour un substitut', 'Ce sens conviendrait à une boisson de remplacement, pas à un bien consommé avec le café.']], 'recognition')] },
    { id: 'supply-shift', title: 'Le grain devient plus cher', human: 'Chaque unité coûte maintenant 2 € de plus à préparer. À prix de vente inchangé, certains cafés ne veulent plus produire autant. Ce changement concerne les coûts : l’offre se déplace vers le haut, puis la hausse du prix réduit les achats sur la demande inchangée.', economist: 'Un coût d’input plus élevé déplace S à gauche/vers le haut. Avec D inchangée : p* augmente et Q* diminue.', exam: 'Higher input costs reduce supply, raising price and lowering equilibrium quantity.', why: ['Le vendeur doit être compensé davantage pour la même unité.', 'À l’ancien prix, la quantité offerte baisse ; la pénurie pousse le prix vers le haut.', 'Les consommateurs répondent au prix final plus élevé le long de D ; leurs goûts n’ont pas changé.'], example: 'Offre construite pS = 4 + Q, demande pD = 10 − Q. 10 − Q = 4 + Q ⇒ Q = 3 et p = 7, au lieu de Q = 4 et p = 6.', me: 'Tu es vendeur : tu n’as pas envie de préparer moins par humeur. Le même café coûte davantage, donc tu réclames un prix plus élevé.', diagram: supplyShiftGraph, refs: ['3'], provenance: 'peda', checks: [num('supply-shock-q', 'Quel Q résout 10 − Q = 4 + Q ?', 3, '6 = 2Q, donc Q = 3 et p = 7.', 'unités'), choice('supply-or-demand', 'Le coût des grains monte : quelle courbe change d’abord ?', 'L’offre', 'C’est un coût de production. Le mouvement final des achats le long de D est une réaction.', [['La demande, parce que le prix final augmente', 'Cela inverse cause et réaction : le prix final monte parce que S a changé.']], 'recognition')] },
    { id: 'two-shocks', title: 'Deux chocs : accepte ce qu’on ne peut pas savoir', human: 'Imagine en même temps davantage d’étudiants et des grains plus chers. Les deux changements poussent le prix vers le haut. Pour la quantité, l’arrivée d’acheteurs pousse vers plus de cafés tandis que le coût pousse vers moins : leur taille relative décide.', economist: 'D à droite et S à gauche : prix en hausse, quantité ambiguë sans magnitude des chocs.', exam: 'Both shocks raise price, but their effects on equilibrium quantity oppose each other.', why: ['Un résultat est certain si les deux effets partiels ont le même signe.', 'Des effets de signes opposés ne se départagent pas sans information supplémentaire.', 'Ambigu ne signifie pas inchangé : hausse, baisse ou stabilité restent possibles.'], example: 'Base pD = 10 − Q, pS = 2 + Q : Q = 4. Si pD devient 14 − Q et pS 4 + Q, Q = 5. Si pS devient 8 + Q au lieu de 4 + Q, Q = 3. Dans les deux cas p augmente : 9 ou 11.', me: 'À l’examen, tu peux gagner le point en expliquant précisément l’ambiguïté au lieu d’inventer une flèche pour Q.', refs: ['3'], provenance: 'peda', checks: [choice('ambiguity', 'D se déplace à droite et S à gauche, sans tailles données. Quelle conclusion est justifiée ?', 'p augmente ; Q peut monter, baisser ou rester stable', 'Les deux chocs font monter p mais leurs effets sur Q se compensent plus ou moins.', [['p et Q augmentent forcément', 'Ce serait la conclusion d’un seul choc de demande, pas des deux.'], ['Q reste forcément inchangée', 'Des effets opposés ne sont pas forcément égaux.']])] },
    { id: 'steepness', title: 'Quand les vendeurs peuvent peu s’adapter', human: 'Le campus veut plus de cafés, mais une seule machine limite la production à court terme. La quantité offerte peut peu augmenter ; davantage de l’ajustement passe alors par le prix. Avec des machines disponibles, plus de quantité peut absorber le même choc de demande.', economist: 'Pour un choc donné, une offre plus raide implique une plus forte réaction du prix et une plus faible réaction de quantité, sous les hypothèses usuelles.', exam: 'A less responsive supply produces a larger price response to the same demand shift.', why: ['Le nouvel équilibre doit résorber le même excès de demande initial.', 'Si la quantité s’ajuste peu du côté offre, le prix doit davantage décourager la demande.', 'La pente est exprimée avec des unités ; l’élasticité enseignera ensuite comment comparer des réactions en pourcentages.'], example: 'Deux marchés construits partent de (Q, p) = (4, 6). Choc pD : 10 − Q → 14 − Q. Offre p = 2 + Q : nouveau (6, 8). Offre raide p = −6 + 3Q : nouveau (5, 9). Le prix augmente de 3 au lieu de 2 ; Q augmente de 1 au lieu de 2.', me: 'Tu veux un café pendant une panne de machine. Un désir d’achat supérieur ne crée pas instantanément une capacité supplémentaire.', refs: ['3', '5'], provenance: 'peda', checks: [choice('steep-supply', 'Pour le même choc de demande positif, une offre plus raide donne généralement…', 'Une hausse de prix plus forte et une hausse de Q plus faible', 'Le prix doit faire davantage du travail d’ajustement.', [['Une hausse de Q plus forte car la courbe monte vite', 'Monter vite en prix signifie justement qu’il faut beaucoup de hausse de prix pour un peu de Q supplémentaire.']], 'graph')] },
    { id: 'aggregation', title: 'Un marché additionne des achats, pas des prix', human: 'Deux étudiants n’ont pas la même disposition à payer. Au même prix, demande à chacun combien il achète, puis additionne les unités. Si l’un répondrait une quantité négative avec sa formule, il achète zéro : personne ne vend ici une « consommation négative ».', economist: 'Demande privée de marché : sommation horizontale QD(p) = Σ max(0, qi(p)). La courbe agrégée peut avoir un coude.', exam: 'Market demand is the horizontal sum of non-negative individual quantities at each price.', why: ['Tous paient le même prix pour le bien homogène.', 'Ce que le marché absorbe est le nombre total d’unités, donc une somme de quantités.', 'Un acheteur sort du marché au-dessus de son prix de réserve ; conserver sa demande négative fausserait la somme.'], example: 'Exemple L4 : qH = max(0, 10 − p), qL = max(0, 5 − p). À p = 6 : 4 + 0 = 4, pas 4 + (−1) = 3. À p = 4 : 6 + 1 = 7.', me: 'À 6 €, ton ami renonce au café. Tu n’en achètes pas une unité de moins parce que sa formule non tronquée vaut −1.', refs: ['4.7', '20.2'], provenance: 'recalc', checks: [num('aggregate', 'Avec qH = max(0, 10 − p) et qL = max(0, 5 − p), quel est QD à p = 6 ?', 4, 'qH = 4 ; qL = 0. La somme est 4.', 'unités', [{ value: 3, feedback: 'Tu as conservé −1 pour le second acheteur. Tronque chaque demande à zéro avant de sommer.' }])] },
    { id: 'domain', title: 'Vérifie la réponse avant de l’annoncer', human: 'Une formule linéaire est un modèle sur un domaine ; elle n’oblige pas un vendeur à offrir une quantité négative. Après un calcul, réinjecte toujours le prix dans les deux plans et vérifie les unités. Une équation correcte avec un mauvais domaine peut produire un résultat économique impossible.', economist: 'Vérifications : Q ≥ 0, p admissible, QD(p*) = QS(p*), courbe et segment pertinents, unités cohérentes.', exam: 'Check non-negativity, the relevant segment and the consistency of both market plans.', why: ['Les signes et les segments traduisent ce que les acteurs peuvent réellement choisir.', 'Remplacer la solution dans les deux côtés détecte une erreur d’algèbre ou de donnée.', 'Le récit causal doit correspondre au déplacement initial, pas seulement au résultat numérique.'], example: 'Pour QS = p − 2 à p = 1, l’offre économique est zéro, pas −1. Pour l’équilibre calculé p = 6, les deux formules valent 4 : cohérence confirmée.', me: 'Avant de rendre : « qui a changé ? à prix donné que veut-il faire ? quel déséquilibre ? quelle réaction de prix ? ». Tu peux reconstruire le graphique avec ces quatre questions.', refs: ['3', '20.2', '20.8'], provenance: 'peda', checks: [{ kind: 'text', id: 'explain-demand-shock', q: 'Explique en deux phrases pourquoi l’arrivée d’étudiants fait monter p et Q, offre inchangée.', dim: 'intuition', tags: [], rubric: [{ id: 'at-price', label: 'Plus d’achats à prix donné', patterns: [/prix (donne|inchange|constant)/i, /meme prix/i] }, { id: 'shortage', label: 'Pénurie puis hausse du prix', patterns: [/penurie|exces de demande/i] }, { id: 'supply', label: 'Réaction sur l’offre inchangée', patterns: [/offre.*(inchang|meme)|quantite offerte|vendeurs.*(plus|augment)/i] }], model: 'À l’ancien prix, davantage d’étudiants veulent acheter, ce qui crée une pénurie. Le prix monte : les vendeurs augmentent leur quantité offerte sur S inchangée et le nouveau Q dépasse l’ancien.' }] },
  ],
  chain: [{ text: 'Identifier le choc initial', because: 'Le changement de revenu, goût ou coût indique quel plan est modifié, indépendamment du prix du bien.' }, { text: 'Comparer QD et QS à l’ancien prix', because: 'La relation modifiée crée une pénurie ou des invendus.' }, { text: 'Déduire la pression sur le prix', because: 'Les achats insatisfaits poussent p vers le haut ; les invendus poussent p vers le bas.' }, { text: 'Suivre les réactions sur les courbes inchangées', because: 'Le nouveau prix change les quantités voulues sans déplacer automatiquement toutes les courbes.' }, { text: 'Vérifier le nouvel équilibre et le domaine', because: 'Les quantités souhaitées doivent être égales et économiquement possibles.' }],
  teach: { prompt: 'Un café normal devient plus populaire tandis que le prix de ses grains augmente. Explique à un ami ce qui change à prix donné, ce qui arrive au prix et pourquoi tu ne peux pas toujours signer la variation de Q.', links: [{ id: 'd', label: 'Le goût déplace D', explain: 'Plus de café est voulu au même prix.', patterns: [/demande.*(droite|augment|plus)/i, /plus.*(meme|donne).*prix/i] }, { id: 's', label: 'Le coût déplace S', explain: 'À prix de vente donné, moins est offert.', patterns: [/offre.*(gauche|diminu|moins)|co[uu]t.*(augment|plus)/i] }, { id: 'p', label: 'Les deux poussent p vers le haut', explain: 'Chaque choc crée un excès de demande à l’ancien prix.', patterns: [/prix.*(augment|mont|hauss)/i] }, { id: 'q', label: 'Q reste ambiguë', explain: 'Les effets de quantité sont opposés ; il faut leur taille.', patterns: [/ambigu|taille|ampleur|oppos|peut.*(augment|mont).*(baiss|diminu)/i] }], errors: [{ mis: 'shift-vs-movement', patterns: [/prix.*(seul|lui-meme).*deplace.*demande/i], refine: 'Le prix propre fait choisir un point le long de D. Un goût différent déplace D à prix donné.' }, { mis: 'ambiguous-is-zero', patterns: [/quantite.*(forcement|necessairement).*(inchang|stable)/i], refine: 'Ambigu ne veut pas dire inchangé : les deux chocs peuvent être de tailles différentes.' }], model: 'La popularité augmente les achats souhaités à chaque prix : D se déplace à droite. Les grains plus chers réduisent l’offre à chaque prix : S se déplace à gauche. Les deux forces augmentent p. La première augmente Q tandis que la seconde le réduit : sans tailles relatives, la variation de Q est ambiguë.' },
  exam: { id: 'sd-guided-exam', title: 'Coffee market: demand and supply shocks', ref: '3', note: 'Entraînement construit à partir de L2 et du format de raisonnement SSE. Les nombres et la correction ne constituent pas un corrigé officiel.', statement: 'A competitive coffee market has demand QD = 10 − p and supply QS = p − 2, with non-negative quantities. A rise in student numbers changes demand to QD = 14 − p. Later, input costs rise and supply becomes QS = p − 4. Prices are euros per unit and quantities are units per week. (a) Find the initial equilibrium. (b) Find the equilibrium after the demand shock alone. (c) Find the equilibrium after both shocks and explain why the direction of the quantity change cannot be inferred from the directions of the shocks alone.', parts: [{ kind: 'num', id: 'a', prompt: 'Initial equilibrium', answers: [{ label: 'p', value: 6 }, { label: 'Q', value: 4 }], explain: '10 − p = p − 2 ⇒ p = 6, Q = 4.', tags: ['sd'] }, { kind: 'num', id: 'b', prompt: 'After demand rises, before the supply shock', answers: [{ label: 'p', value: 8 }, { label: 'Q', value: 6 }], explain: '14 − p = p − 2 ⇒ p = 8, Q = 6.', tags: ['sd'] }, { kind: 'num', id: 'c-num', prompt: 'After both shocks', answers: [{ label: 'p', value: 9 }, { label: 'Q', value: 5 }], explain: '14 − p = p − 4 ⇒ p = 9, Q = 5. This particular demand shock outweighs the negative supply effect on Q.', tags: ['sd'] }, { kind: 'text', id: 'c-explain', prompt: 'Explain the separate effects and the general ambiguity in English.', rubric: [{ id: 'd', label: 'Demand right', patterns: [/demand.*(right|increase|higher)/i] }, { id: 's', label: 'Supply left', patterns: [/supply.*(left|decrease|lower)|input cost/i] }, { id: 'ambiguous', label: 'Opposite quantity effects', patterns: [/ambiguous|oppos|relative (size|magnitude)/i] }], model: 'Higher demand and lower supply both raise price. Their effects on quantity oppose each other, so quantity is ambiguous without magnitudes. Here the demand increase is larger and quantity rises from 4 to 5.', tags: ['sd'] }], logic: ['Déplacer D pour l’arrivée d’acheteurs, S pour les coûts.', 'Résoudre QD = QS dans chacun des trois régimes.', 'Distinguer le résultat numérique de ce cas et la conclusion générale sans tailles.'], calc: ['Base : 10 − p = p − 2 ⇒ p = 6, Q = 4.', 'Demande seule : 14 − p = p − 2 ⇒ p = 8, Q = 6.', 'Les deux : 14 − p = p − 4 ⇒ p = 9, Q = 5.'], graph: ['Q horizontal, p vertical. D initiale : p = 10 − Q ; nouvelle : p = 14 − Q.', 'S initiale : p = 2 + Q ; nouvelle : p = 4 + Q.', 'Marquer (4,6), (6,8), puis (5,9) en coordonnées (Q,p).'], modelAnswer: 'Initially, 10 − p = p − 2 gives p = 6 and Q = 4. The demand shift alone gives p = 8 and Q = 6. With both shocks, 14 − p = p − 4 gives p = 9 and Q = 5. Both shocks raise price; demand raises quantity whereas lower supply reduces it. The net quantity effect is therefore ambiguous in general, although quantity increases in these numerical data.' },
  ladder: [
    [choice('r1-a', 'Quantity demanded et demand : quelle différence ?', 'Un point à un prix donné, contre la relation entière entre prix et quantités', 'Une variation du prix propre change le point, pas automatiquement la relation.', [['Aucune : les deux désignent toujours la courbe entière', 'Cette confusion empêche de distinguer mouvement et déplacement.']], 'terminology'), choice('r1-b', 'Excess supply désigne ici…', 'QS − QD lorsque cette différence est positive', 'C’est un excès d’unités proposées, pas une aire de gain monétaire.', [['Le profit de tous les vendeurs', 'C’est une autre notion, exprimée en monnaie et non en unités.']], 'terminology')],
    [choice('r2-a', 'Un input devient moins cher, D inchangée. Résultat usuel ?', 'p baisse et Q augmente', 'S se déplace à droite ; le nouveau prix plus bas fait augmenter les achats.', [['p et Q baissent', 'La baisse du coût permet davantage de quantité, pas moins.']]), { kind: 'order', id: 'r2-b', q: 'Reconstitue un choc positif de demande.', dim: 'intuition', tags: [], items: ['Plus d’achats souhaités à prix donné', 'Excès de demande à l’ancien prix', 'Hausse du prix', 'Hausse de la quantité offerte le long de S'] }],
    [num('r3-a', 'Nouveau marché : QD = 18 − 2p ; QS = p − 3. Calcule p*.', 7, '18 − 2p = p − 3 ⇒ 21 = 3p ⇒ p = 7 ; Q = 4.', '€'), num('r3-b', 'Avec pD = 24 − 2Q et pS = 6 + Q, calcule Q*.', 6, '24 − 2Q = 6 + Q ⇒ Q = 6, p = 12.', 'unités')],
    [choice('r4-a', 'D à gauche et S à droite, tailles inconnues : conclusion certaine ?', 'Le prix baisse ; Q est ambiguë', 'Les deux forces baissent p, mais l’une réduit Q et l’autre l’augmente.', [['Q baisse et p est ambigu', 'C’est l’autre combinaison de signes. Refais chaque choc séparément.']]), num('r4-b', 'Deux demandes q1 = max(0, 8 − p) et q2 = max(0, 3 − p). À p = 5, quel total ?', 3, '3 + 0 = 3 ; la seconde demande est tronquée à zéro.', 'unités')],
    [choice('r5-a', 'Quelle phrase EN décrit correctement une hausse du prix propre ?', 'Quantity demanded falls along an unchanged demand curve.', 'La relation est conservée ; le point se déplace.', [['Demand shifts left because its own price rises.', 'Il manque un déterminant autre que le prix propre.']], 'english'), { kind: 'text', id: 'r5-b', q: 'EN : explain why higher input costs raise the market price.', dim: 'english', tags: [], lang: 'en', rubric: [{ id: 's', label: 'Supply falls at a given price', patterns: [/supply.*(fall|decreas|left)|less.*suppl/i] }, { id: 'p', label: 'Shortage raises price', patterns: [/shortage|excess demand/i] }], model: 'Higher input costs reduce supply at each price. At the old price there is excess demand, creating upward pressure on price.' }],
  ],
  acceptance: [{ text: 'Je distingue un plan d’achat d’un plan de vente.', why: ['Je nomme les acteurs et ce qu’ils prennent comme donné.'] }, { text: 'Je trouve et vérifie p* et Q*.', why: ['J’égalise QD et QS puis remplace la solution dans les deux relations.'] }, { text: 'Je sépare déplacement et mouvement.', why: ['Je pose la question « au même prix, voudrait-on plus ou moins ? ».'] }, { text: 'Je peux expliquer une pénurie et des invendus.', why: ['Je déduis une pression de prix des décisions incompatibles.'] }, { text: 'Je ne signe pas une variable ambiguë.', why: ['Je compare les effets des deux chocs séparément et leur taille.'] }, { text: 'Je respecte les domaines et les unités.', why: ['Je tronque les demandes négatives et garde le même marché dans toutes les relations.'] }],
});

const budgetGraph: LessonDiagramSpec = {
  kind: 'curves', title: 'A2 : ton budget face à tes préférences', xLabel: 'R, unités de R', yLabel: 'L, unités de L', xMax: 10, yMax: 32, refs: ['4.2', '15:A2#2.2'],
  note: 'R horizontal, L vertical. Budget exact L = 30 − 3R. L’indifférence U = LR = 75 est représentée par des points exacts reliés pour la lecture ; les segments sont une approximation visuelle de l’hyperbole.',
  curves: [{ label: 'Budget : L = 30 − 3R', color: 'buyer', points: [[0, 30], [10, 0]], explain: 'Paniers coûtant exactement 1 200 avec pL = 40 et pR = 120.' }, { label: 'Indifférence U = 75', color: 'planner', points: [[2.5, 30], [3, 25], [5, 15], [7.5, 10], [10, 7.5]], explain: 'Chaque point donne LR = 75. La tangence est (R,L) = (5,15).' }],
  markers: [{ x: 5, y: 15, label: 'Optimum : R = 5, L = 15' }, { x: 4, y: 20, label: 'Coûte 1 280 : inaccessible' }], initial: 5,
};
const consumerPriceGraph: LessonDiagramSpec = {
  ...budgetGraph, title: 'Le prix de R monte, ton revenu nominal reste 1 200',
  note: 'Après pR = 150, L = 30 − 3,75R. L’intercept vertical reste 30, l’horizontal passe de 10 à 8. Nouveau choix (R,L) = (4,15). Les indifférences sont des échantillons exacts, segments visuels approximatifs.',
  curves: [budgetGraph.curves[0], { label: 'Nouveau budget : L = 30 − 3,75R', color: 'third', points: [[0, 30], [8, 0]], explain: 'Même revenu, R plus cher : pouvoir d’achat réduit.' }, { label: 'Nouvelle indifférence : U = 60', color: 'planner', points: [[2, 30], [3, 20], [4, 15], [6, 10], [8, 7.5]], explain: 'Au nouvel optimum, LR = 60 au lieu de 75.' }], markers: [{ x: 5, y: 15, label: 'Ancien choix' }, { x: 4, y: 15, label: 'Nouveau choix' }], initial: 4,
};
const CONSUMER = guidedLesson({
  id: 'consumer-guided', topic: 'consumer', node: 'consumer', title: 'Consommateur — choisis ce que ton budget permet', mechanism: 'Préférences, arbitrage et contrainte', teaser: 'Un panier peut te plaire davantage sans être achetable. Tu vas faire parler ton budget, découvrir ce que signifie MRS, puis savoir quand une tangence, un coin ou un coude décide.',
  actors: actors({ buyer: ['Toi, consommateur', 'répartis 1 200 entre L et R', 'le panier accessible que tu préfères'], producer: ['Les vendeurs', 'affichent pL = 40 et pR = 120', 'être payés pour les quantités achetées'], planner: ['Toi, analyste', 'distingues classement et faisabilité', 'retrouver le choix sans réciter une tangence au hasard'] }),
  blocks: [
    { id: 'scene', title: 'Ce que tu veux et ce que tu peux sont deux questions', human: 'Tu as 1 200 à dépenser entre deux biens L et R. Le premier coûte 40 et le second 120. Tu peux préférer un panier très généreux, mais cette préférence ne finance pas l’achat : commence par vérifier ce que tu peux payer.', economist: 'Le consommateur maximise ses préférences sous pL·L + pR·R ≤ I. L’objectif et la contrainte jouent des rôles différents.', exam: 'The consumer chooses the most preferred affordable bundle.', why: ['Les préférences classent les paniers, y compris ceux qui dépassent le budget.', 'Le budget élimine les paniers impossibles avant la comparaison finale.', 'Optimiser sous contrainte ne consiste donc pas à choisir l’utilité numérique la plus élevée dans une liste sans vérifier son coût.'], example: 'A2 : (L,R) = (20,4) donne U = 80 mais coûte 40×20 + 120×4 = 1 280. (15,5) donne U = 75 et coûte 1 200 : le second est accessible, le premier non.', me: 'Tu préfères peut-être un ordinateur plus performant, mais tu ne peux pas ajouter les 80 manquants à ton budget simplement parce que son score est meilleur.', diagram: budgetGraph, refs: ['4.2', '15:A2#2.2', '20.1'], provenance: 'recalc', checks: [num('bundle-cost', 'Combien coûte (L,R) = (20,4) ?', 1280, '40×20 + 120×4 = 800 + 480 = 1 280.', '€'), choice('affordable', 'Le panier (20,4) est-il disponible avec I = 1 200 ?', 'Non, même s’il donne plus d’utilité', 'Il dépasse la contrainte de 80.', [['Oui car U = 80 dépasse U = 75', 'Une préférence ne rend pas un panier payable.']])] },
    { id: 'ordinal', title: 'L’utilité est un classement, pas un thermomètre du bonheur', human: 'Le modèle U = LR attribue un nombre à chaque panier pour représenter tes préférences. Dire U = 80 plutôt que 40 signifie que le premier panier est préféré ; cela ne mesure pas deux fois plus de bonheur. Une transformation qui garde l’ordre des paniers représente les mêmes choix.', economist: 'L’utilité est ordinale. Pour L,R positifs, U = LR et V = √(LR) classent les paniers dans le même ordre.', exam: 'Utility is ordinal: a strictly increasing transformation preserves the preference ranking.', why: ['Le choix a besoin d’un ordre entre paniers, pas d’une unité universelle de bonheur.', 'La racine carrée est croissante : si LR est plus grand, sa racine l’est aussi.', 'Les niveaux et les dérivées changent, mais l’arbitrage cohérent et le panier optimal restent les mêmes.'], example: 'Paniers (15,5) et (24,2) : U = 75 et 48 ; V ≈ 8,66 et 6,93. Le classement est identique malgré des écarts numériques différents.', me: 'Ton application peut changer la notation de 75 à 8,66 sans changer le panier que tu choisirais.', refs: ['4.1'], provenance: 'peda', checks: [choice('ordinal', 'U(A) = 80 et U(B) = 40 permettent d’affirmer…', 'A est préféré à B selon ces préférences', 'Le score classe les paniers ; il ne mesure pas un rapport de bonheur.', [['A apporte exactement deux fois plus de bonheur', 'Ce rapport disparaît sous une transformation croissante pourtant équivalente.']], 'terminology')] },
    { id: 'budget', title: 'Lis les intercepts avant de calculer une pente', human: 'Si tu consacres tout ton argent à L, tu peux en acheter 30. Si tu prends seulement R, tu peux en acheter 10. Entre ces extrêmes, acheter un R de plus oblige à abandonner trois L : c’est le compromis offert par le marché.', economist: 'Avec R horizontal et L vertical : 40L + 120R = 1 200 ⇒ L = 30 − 3R. Pente = −pR/pL = −3.', exam: 'With R on the horizontal axis, the budget slope is −pR/pL = −3.', reveal: { q: 'Un R coûte 120 et un L coûte 40. Combien de L dois-tu sacrifier pour payer un R de plus ?', options: [{ text: '3 L', correct: true, feedback: '120/40 = 3. Voilà pourquoi le ratio de prix est la pente en valeur absolue.' }, { text: '1/3 L', feedback: 'Ce serait le coût d’un L exprimé en R ; tes axes sont dans l’autre sens.' }, { text: '120 L', feedback: '120 est une monnaie par R, pas un nombre de L. Divise par le prix d’un L.' }], formula: 'pL·L + pR·R = I ⇒ L = I/pL − (pR/pL)R = 30 − 3R', tags: ['consumer'] }, why: ['Les intercepts achètent un seul bien : ils sont donc I divisé par son prix.', 'Le budget permet d’échanger 120 de dépense sur R contre 120 de dépense sur L.', 'Le nombre de L sacrifiés vaut 120/40 ; le signe négatif traduit la réduction de L.'], example: 'Passe de (L,R) = (18,4) à (15,5) : −3 L et +1 R, coût inchangé de 1 200.', me: 'Tu ajoutes un R au panier. Pour rester à la caisse avec la même somme, tu retires trois L.', diagram: budgetGraph, refs: ['4.2', '15:A2#2.2'], provenance: 'recalc', checks: [num('r-intercept', 'Combien de R si tout le budget de 1 200 va à R au prix 120 ?', 10, '1 200/120 = 10.', 'R'), choice('slope-axis', 'R horizontal et L vertical : valeur absolue de la pente budgétaire ?', 'pR/pL = 3', 'Le numérateur est le prix du bien horizontal.', [['pL/pR = 1/3', 'Ce ratio conviendrait à L horizontal et R vertical.']], 'graph')] },
    { id: 'marginal', title: 'Le prochain bien compte autrement selon ce que tu as déjà', human: 'Avec U = LR, un L de plus est d’autant plus utile que tu as déjà de R pour en profiter. À l’inverse, un R de plus vaut davantage quand L est abondant. La décision d’ajuster ton panier compare ce qu’ajoute chaque bien à la marge.', economist: 'Pour U = LR : MU_L = R et MU_R = L. MU désigne la dérivée de l’utilité par rapport au bien concerné.', exam: 'For U = LR, the marginal utilities are MU_L = R and MU_R = L.', why: ['Si R est fixé, ajouter un L augmente le produit LR de R.', 'Si L est fixé, ajouter un R augmente LR de L.', 'On compare des variations locales pour savoir si déplacer un peu de dépense améliore le panier.'], example: 'À (L,R) = (15,5), un L de plus à R fixé augmente U de 5 ; un R de plus à L fixé augmente U de 15. Les unités coûtent cependant 40 et 120 : il faut encore comparer par euro.', me: 'Ne choisis pas R seulement parce que son MU vaut 15 contre 5 : un R coûte trois fois plus cher.', refs: ['4.1', '4.3'], provenance: 'peda', checks: [num('mu-r', 'Avec U = LR au panier (L,R) = (15,5), quel est MU_R ?', 15, 'La dérivée par rapport à R est L ; ici L = 15.', 'unités d’utilité/R'), choice('mu-only', 'MU_R > MU_L suffit-il pour consacrer toute la dépense à R ?', 'Non : il faut comparer l’utilité marginale par euro', 'R peut être plus utile par unité et plus cher dans la même proportion.', [['Oui, le MU le plus élevé décide toujours', 'Tu ignores le coût d’obtenir cette unité.']])] },
    { id: 'mrs', title: 'MRS : ton échange volontaire, pas celui du magasin', human: 'Sur une même courbe d’indifférence, tu peux perdre un peu de L et gagner un peu de R tout en restant aussi satisfait. La quantité de L que tu accepterais de sacrifier pour un R supplémentaire décrit ton arbitrage personnel. Le magasin propose un autre arbitrage, donné par ses prix.', economist: 'Avec R horizontal : MRS_RL = MU_R/MU_L = L/R, valeur absolue de la pente d’indifférence. L’unité est L par R.', exam: 'MRS_RL measures how much L the consumer is willing to give up for one extra R at constant utility.', why: ['Garder U constant impose MU_R·dR + MU_L·dL = 0.', 'Donc dL/dR = −MU_R/MU_L ; le ratio positif mesure le sacrifice consenti.', 'Si ton sacrifice accepté dépasse le sacrifice demandé par le marché, acheter un peu plus de R peut améliorer ton panier.'], example: 'Au panier (15,5), MRS_RL = 15/5 = 3 L par R. Au panier (24,2), MRS = 12 : tu es prêt à sacrifier davantage de L pour R parce que R est relativement rare pour toi.', me: 'Tu demandes « combien de L abandonnerais-je volontiers pour un peu plus de R ? », puis compares ce chiffre aux trois L réclamés par les prix.', diagram: budgetGraph, refs: ['4.2'], provenance: 'peda', checks: [num('mrs', 'À (L,R) = (24,2), quelle est MRS_RL pour U = LR ?', 12, 'MU_R/MU_L = L/R = 24/2 = 12.', 'L par R'), choice('mrs-meaning', 'MRS mesure…', 'Ton arbitrage à satisfaction constante', 'Il vient des préférences ; le ratio des prix vient du marché.', [['Le prix relatif, quelle que soit ta préférence', 'Ce serait pR/pL. Les deux ratios ne coïncident qu’à certains optima.']], 'terminology')] },
    { id: 'last-euro', title: 'Pourquoi le dernier euro doit faire le même travail', human: 'Si un euro dépensé en R t’ajoute plus de satisfaction qu’un euro dépensé en L, tu peux transférer un peu de dépense vers R. Cela améliore ton panier sans dépasser ton budget. À un optimum intérieur régulier, ce petit transfert ne doit plus aider dans aucun sens.', economist: 'Optimum intérieur : MU_R/pR = MU_L/pL, soit MRS_RL = pR/pL. Il faut ajouter la contrainte budgétaire et vérifier les conditions d’intérieur.', exam: 'At an interior optimum, marginal utility per euro is equal across goods.', reveal: { q: 'Quelle comparaison empêche un transfert d’un euro d’améliorer le panier ?', options: [{ text: 'MU_R/pR = MU_L/pL', correct: true, feedback: 'Oui : même gain marginal pour le dernier euro dans les deux usages.' }, { text: 'MU_R = MU_L', feedback: 'Cela comparerait des unités dont les prix peuvent différer.' }, { text: 'R = L', feedback: 'L’égalité des quantités n’est pas l’égalité des gains par euro.' }], formula: 'MU_R/pR = MU_L/pL ⇔ L/120 = R/40 ⇔ L/R = 3 ; avec 40L + 120R = 1 200', tags: ['consumer'] }, why: ['Le budget reste constant si on déplace une petite somme d’un bien à l’autre.', 'Si les gains par euro diffèrent, ce transfert augmente U : le panier n’était pas optimal.', 'L’égalité seule décrit un ensemble de paniers ; le budget choisit celui que tu peux atteindre.'], example: 'À (15,5), MU_R/pR = 15/120 = 0,125 et MU_L/pL = 5/40 = 0,125. Les deux derniers euros font le même travail.', me: 'Tu répartis un euro supplémentaire. À l’optimum, aucun des deux rayons n’a un avantage marginal sur l’autre.', diagram: budgetGraph, refs: ['4.3'], provenance: 'peda', checks: [{ kind: 'build', id: 'tangency', q: 'Reconstruis la condition de tangence avec R horizontal.', lhs: 'MRS_RL', tokens: ['MU_R', '/', 'MU_L', '=', 'pR', '/', 'pL'], accept: [['MU_R', '/', 'MU_L', '=', 'pR', '/', 'pL']], dim: 'formula', tags: [], explain: 'Ton sacrifice MU_R/MU_L doit égaler le sacrifice demandé pR/pL.' }] },
    { id: 'solve', title: 'Résous le panier A2, pas seulement une équation', human: 'La tangence dit L = 3R. Le budget dit que les deux biens doivent ensemble coûter 1 200. En combinant les deux, tu obtiens un panier unique ; tu peux ensuite vérifier son coût et son utilité.', economist: 'U = LR : moitié de la dépense dans chaque bien. Cela ne signifie pas la moitié des unités.', exam: 'The optimum is L = 15 and R = 5, spending 600 on each good.', why: ['Avec L = 3R, le budget devient 40×3R + 120R = 1 200.', 'Donc 240R = 1 200 : R = 5 et L = 15.', 'Les deux biens sont désirables, la solution est positive, et U = LR donne ici un optimum intérieur cohérent.'], example: 'A2 : R = 5, L = 15 ; dépenses 120×5 = 600 et 40×15 = 600 ; U = 75. Le panier (24,2) coûte aussi 1 200 mais U = 48.', me: 'Tu n’achètes pas le même nombre de chaque bien : tu réserves la même somme à chacun parce que les exposants de U = LR sont égaux.', diagram: budgetGraph, refs: ['4.3', '15:A2#2.2'], provenance: 'recalc', result: ['Panier optimal accessible', 'L = 15 ; R = 5'], checks: [num('optimal-r', 'Trouve R dans 40(3R) + 120R = 1 200.', 5, '240R = 1 200 ⇒ R = 5 ; L = 3R = 15.', 'R'), num('optimal-u', 'Quelle utilité donne le panier optimal (L,R) = (15,5) ?', 75, 'U = L×R = 15×5 = 75.', 'utilité')] },
    { id: 'price-change', title: 'R devient plus cher : qu’est-ce qui a vraiment diminué ?', human: 'Le prix de R passe de 120 à 150. Tu as toujours 1 200 en argent, mais ce revenu achète moins de R. Le budget pivote : tout-L reste possible, tout-R passe de dix à huit unités.', economist: 'Le revenu nominal I est inchangé. Le pouvoir d’achat baisse ; pente budgétaire −pR/pL = −3,75. Nouveau choix U = LR : L = 15, R = 4.', exam: 'The price rise reduces purchasing power, not nominal income. The new optimum is L = 15, R = 4.', why: ['Le prix de L et I ne changent pas, donc l’intercept L = 30 reste fixe.', 'Chaque R consomme davantage du budget, donc l’intercept R = 8 se rapproche de l’origine.', 'U = LR partage encore la dépense en deux : 600/40 = 15 et 600/150 = 4.'], example: 'Nouveau budget 40L + 150R = 1 200. Au choix (15,4), coût = 600 + 600 = 1 200 ; U = 60 au lieu de 75. Aucun euro de revenu nominal n’a disparu.', me: 'Tu vois le même solde bancaire mais les articles coûtent plus cher. Dis « je peux acheter moins », pas « mon salaire a baissé ».', diagram: consumerPriceGraph, refs: ['4.2', '15:A2#2.2', '20.1'], provenance: 'recalc', checks: [num('new-r', 'Après pR = 150, avec U = LR et I = 1 200, quel R est optimal ?', 4, 'La moitié de la dépense, 600, va à R : 600/150 = 4.', 'R'), choice('nominal', 'Après cette hausse de prix, le revenu nominal vaut…', '1 200, comme avant', 'Le prix change le pouvoir d’achat, pas le montant I donné.', [['960, car l’utilité a baissé de 20 %', 'Une utilité ordinale ne convertit pas automatiquement une perte de satisfaction en revenu nominal.']])] },
    { id: 'substitution-income', title: 'Le prix agit par deux portes', human: 'Quand R devient plus cher, il est moins intéressant relativement à L : tu substitues vers L. Le même revenu permet aussi moins de consommation totale : c’est l’effet de revenu. Même si l’effet total sur L est nul dans cet exemple, cela ne veut pas dire que ces deux forces n’existent pas.', economist: 'Effet de substitution : réaction au prix relatif à utilité compensée. Effet de revenu : réaction à la modification du pouvoir d’achat. La décomposition demande un benchmark de compensation précisé.', exam: 'A price change combines a substitution effect with an income effect.', why: ['Le nouveau ratio de prix change ce que coûte R en unités de L, même si tu reçois de l’argent en compensation.', 'La baisse de pouvoir d’achat agit comme un resserrement des possibilités.', 'Pour U = LR, L est normal : la substitution vers L et l’effet de revenu négatif sur L s’opposent et se compensent dans ce cas.'], example: 'Base A2 : L = 15, R = 5. Après pR = 150 : L = 15, R = 4. Le L inchangé ne prouve pas « aucun effet » : les effets partiels peuvent se compenser.', me: 'Même si on te rembourse une partie de la hausse, un R coûte encore 3,75 L au lieu de 3. Tu as encore une raison de changer la composition.', diagram: consumerPriceGraph, refs: ['4.6', '15:A2#2.2'], provenance: 'peda', checks: [choice('compensation-price', 'Un transfert d’argent rétablit ton ancienne satisfaction après la hausse de pR. Le prix relatif a-t-il disparu ?', 'Non, R reste relativement plus cher', 'Le transfert déplace le budget parallèlement ; il ne rétablit pas l’ancienne pente.', [['Oui, une compensation supprime tous les effets du prix', 'Elle peut restaurer le niveau de satisfaction sans restaurer les prix relatifs.']])] },
    { id: 'compensation', title: 'Racheter l’ancien panier ou retrouver l’ancienne utilité ?', human: 'Deux compensations portent des noms proches mais ne promettent pas la même chose. L’une finance exactement l’ancien panier aux nouveaux prix. L’autre donne juste assez pour retrouver l’ancienne satisfaction en choisissant un nouveau panier ; rechoisir peut coûter moins que copier l’ancien.', economist: 'Ancien panier accessible et ancienne utilité juste atteinte sont des critères distincts. La stricte amélioration par rechoix demande des conditions régulières ; la garantie générale est « pas moins bien ».', exam: 'Compensating for the old bundle and compensating for the old utility are different criteria.', why: ['Le nouveau prix relatif rend l’ancien panier en général mal adapté.', 'Si l’ancien panier est accessible, le meilleur nouveau choix ne peut pas être pire que lui.', 'Sous convexité stricte et ancienne solution intérieure, le rechoix peut être strictement meilleur ; aux coins, ne promets pas systématiquement une amélioration stricte.'], example: 'Aux nouveaux prix 40 et 150, l’ancien (15,5) coûte 1 350. Avec I = 1 350, le nouvel optimum est L = 16,875, R = 4,5, U = 75,9375 > 75. Juste atteindre U = 75 demande I = √(4×40×150×75) ≈ 1 341,64, donc un transfert ≈ 141,64, contre 150 pour financer l’ancien panier.', me: 'Tu peux reprendre exactement ton ancien panier avec 150 de plus. Mais en réorganisant tes achats, tu peux atteindre l’ancienne satisfaction avec un peu moins.', refs: ['4.6', '16:E2022#Q5'], provenance: 'peda', checks: [num('old-bundle-cost', 'À pL = 40 et pR = 150, combien coûte l’ancien panier (L,R) = (15,5) ?', 1350, '40×15 + 150×5 = 600 + 750 = 1 350.', '€'), choice('old-bundle-guarantee', 'Si un transfert rend l’ancien panier accessible, quelle garantie générale existe ?', 'Le meilleur nouveau choix est au moins aussi bon que l’ancien', 'Il peut toujours reprendre l’ancien panier, et peut parfois faire mieux.', [['Le consommateur doit acheter exactement l’ancien panier', 'L’accessibilité n’est pas une obligation de copier la composition.']])] },
    { id: 'perfect-substitutes', title: 'Quand un coin remplace la tangence', human: 'Suppose maintenant que deux boissons se remplacent parfaitement pour toi. Si l’une apporte plus de satisfaction par euro, tu dépenses tout dessus. Une jolie tangence intérieure n’existe pas forcément : le bord du budget peut être le bon endroit.', economist: 'Substituts parfaits U = a·x + b·y : comparer a/px et b/py. Un coin si les ratios diffèrent ; tous les paniers du budget sont optimaux s’ils sont égaux.', exam: 'With perfect substitutes, choose the good with the highest marginal utility per euro.', why: ['Les MU sont constants : acheter davantage du meilleur bien ne réduit pas son avantage relatif.', 'Aucun rééquilibrage intérieur n’est nécessaire si les ratios ne deviennent jamais égaux.', 'À égalité des ratios, déplacer la dépense ne change pas l’utilité : le choix n’est pas unique.'], example: 'Exemple construit : U = 2x + y, I = 12, px = 2, py = 2. Gains par euro : 1 contre 0,5. Choisis x = 6, y = 0, U = 12. Si px devient 4, les ratios valent tous deux 0,5 : tout le budget est optimal.', me: 'Si deux applications font exactement le même travail, mais l’une offre deux fois le service pour le même prix, tu n’as pas besoin d’acheter un peu de chaque.', refs: ['4.4'], provenance: 'peda', checks: [num('substitutes-x', 'U = 2x + y, I = 12 et px = py = 2. Quel x optimal ?', 6, '2/2 > 1/2 : toute la dépense va à x, donc x = 12/2 = 6.', 'x'), choice('tie', 'Si a/px = b/py pour des substituts parfaits, que sait-on ?', 'Tout panier sur le budget est optimal', 'Les deux usages de la dépense apportent exactement le même gain.', [['x = y est obligatoirement l’unique optimum', 'Aucune préférence pour l’égalité des unités n’est donnée.']])] },
    { id: 'complements', title: 'Quand il faut un coude, pas un coin', human: 'Une chaussure gauche sans droite ne crée pas une paire supplémentaire. Si tu consommes les biens ensemble dans un rapport fixe, une unité non appariée n’ajoute rien. Tu cherches alors le coude où la proportion utile est respectée.', economist: 'Compléments parfaits U = min(x/a, y/b) : au choix efficace x/a = y/b. Avec paires 1:1, x = y = I/(px + py).', exam: 'For perfect complements, the optimum is at the kink where the required proportions hold.', why: ['Le plus petit nombre de composants complets limite le nombre d’ensembles utilisables.', 'Acheter un composant excédentaire dépense du budget sans augmenter les ensembles.', 'La règle de proportion avec le budget détermine le coude accessible le plus élevé.'], example: 'Exemple construit : U = min(x,y), I = 30, px = 2, py = 3. x = y et 2x + 3y = 30 ⇒ x = y = 6. Le panier (9,4) coûte 30 aussi, mais donne seulement U = 4.', me: 'Tu ne prends pas neuf chaussures gauches et quatre droites sous prétexte que le budget est épuisé : seules quatre paires fonctionnent.', refs: ['4.4'], provenance: 'peda', checks: [num('complements', 'U = min(x,y), I = 30, px = 2, py = 3. Combien de paires optimales ?', 6, 'Une paire coûte 2 + 3 = 5 ; 30/5 = 6.', 'paires'), choice('model-choice', 'Un énoncé dit « toujours consommés en ratio fixe ». Première méthode ?', 'Proportion au coude + budget', 'Les préférences ne sont pas lisses au coude ; une tangence ordinaire ne s’impose pas.', [['Toujours MUx/MUy = px/py puis tangence lisse', 'La condition intérieure régulière n’est pas universelle.']], 'recognition')] },
    { id: 'demand-engel', title: 'De tes choix à une demande : fais varier la bonne chose', human: 'Tu sais maintenant choisir un panier. Pour construire la demande de R, recommence ce choix à plusieurs prix de R en gardant le revenu et pL fixes. Pour une courbe d’Engel, fais varier le revenu au lieu du prix ; ces deux courbes répondent à des questions différentes.', economist: 'Demande individuelle : R*(pR), I et pL constants. Courbe d’Engel : R*(I), prix constants. La demande privée de marché somme horizontalement les choix individuels non négatifs.', exam: 'A demand curve varies the good’s price; an Engel curve varies income, holding prices fixed.', why: ['Les préférences ne suffisent pas à définir un achat ; les contraintes déterminent le choix accessible.', 'Changer un prix et changer le revenu modifie le budget de deux manières différentes : pivot contre déplacement parallèle.', 'Les achats individuels sont ensuite additionnés au même prix, avec zéro pour ceux qui ne participent pas.'], example: 'Pour U = LR et I = 1 200, R*(pR) = 600/pR : à 100, R = 6 ; à 120, R = 5 ; à 150, R = 4. À pR = 120 fixé, I = 1 440 donne R = 6 : c’est un point d’Engel différent.', me: 'Tu peux expliquer deux fois « j’achète 6 R » : soit R est moins cher, soit tu es plus riche. Le résultat identique ne rend pas les causes identiques.', refs: ['4.5', '4.7'], provenance: 'peda', checks: [num('demand-point', 'U = LR, I = 1 200, pR = 100. Quel R optimal ?', 6, '600 vont à R ; 600/100 = 6.', 'R'), choice('engel', 'Pour tracer Engel, tu fais varier…', 'Le revenu, en maintenant les prix constants', 'Cela isole la relation entre ressources et quantité choisie.', [['Le prix de R, revenu constant', 'C’est la construction de la demande de R.']], 'terminology')] },
  ],
  chain: [{ text: 'Classer les paniers avec les préférences', because: 'L’utilité représente un ordre ; ce que tu désires ne dépend pas encore de la faisabilité.' }, { text: 'Limiter le choix aux paniers accessibles', because: 'Les prix et le revenu imposent le budget.' }, { text: 'Comparer le gain marginal par euro', because: 'Un transfert de dépense est profitable si un usage apporte davantage de MU par euro.' }, { text: 'Choisir la méthode adaptée aux préférences', because: 'Tangence intérieure, coin et coude ne sont pas interchangeables.' }, { text: 'Vérifier puis refaire le choix après un choc', because: 'Un changement de prix modifie la contrainte et peut changer le panier, sans changer le revenu nominal.' }],
  teach: { prompt: 'Explique à un ami pourquoi (20,4), pourtant plus utile, n’est pas le choix A2. Puis explique le panier optimal et ce qui change lorsque pR passe à 150. Utilise tes mots avant les sigles.', links: [{ id: 'budget', label: 'Accessibilité prioritaire', explain: '1 280 dépasse le budget de 1 200.', patterns: [/budget|accessible|co[uu]te|1.?280/i] }, { id: 'marginal', label: 'Même gain au dernier euro', explain: 'Une réallocation améliore U tant que MU/prix diffèrent.', patterns: [/par euro|dernier euro|utilite marginale|MU.*p/i] }, { id: 'solve', label: 'Tangence et budget ensemble', explain: 'L = 3R puis le budget donnent L = 15, R = 5.', patterns: [/15.*5|5.*15|tangence.*budget|L\s*=\s*3R/i] }, { id: 'price', label: 'Même revenu, choix changé', explain: 'pR = 150 donne R = 4 ; I reste 1 200.', patterns: [/pouvoir d.achat|nominal.*(inchang|1200|1.?200)|R.*4/i] }], errors: [{ mis: 'utility-cardinal', patterns: [/deux fois plus (heureux|de bonheur)/i], refine: 'U est ordinal : on compare un classement, pas un ratio de bonheur.' }, { mis: 'nominal-income', patterns: [/revenu (nominal )?(baisse|diminue)/i], refine: 'I reste 1 200. C’est le pouvoir d’achat qui baisse lorsque R devient plus cher.' }, { mis: 'universal-tangency', patterns: [/toujours.*tangence|tangence.*toujours/i], refine: 'La tangence suppose un intérieur régulier. Les substituts parfaits et compléments parfaits demandent coins ou coudes.' }], model: 'Le panier (20,4) est préféré dans la liste sans contrainte mais coûte 1 280, au-delà des 1 200 disponibles. Pour U = LR, à l’intérieur, le dernier euro doit apporter la même utilité dans les deux biens : L/120 = R/40, donc L = 3R. Avec le budget, L = 15 et R = 5. Quand pR monte à 150, le revenu nominal reste 1 200 mais le pouvoir d’achat baisse ; le choix devient L = 15, R = 4 et U passe de 75 à 60.' },
  exam: { id: 'consumer-guided-exam', title: 'Consumer choice: budget, price change and compensation', ref: '15:A2#2.2', note: 'Entraînement construit sur la structure d’A2.2 et §4.6. Les prix changés et la compensation sont des variantes pédagogiques ; aucun barème officiel n’est revendiqué.', statement: 'A consumer has utility U(x,y) = xy, income I = 240, and prices px = 4 and py = 12. (a) Find the optimal bundle and utility. (b) The price of y rises to 15, while nominal income stays at 240. Find the new choice and explain the budget change. (c) What income makes the old bundle affordable at the new prices? Is the consumer forced to choose that bundle?', parts: [{ kind: 'num', id: 'a', prompt: 'Initial choice', answers: [{ label: 'x', value: 30 }, { label: 'y', value: 10 }, { label: 'U', value: 300 }], explain: 'Half the income is spent on each good: x = 120/4 = 30, y = 120/12 = 10, U = 300.', tags: ['consumer'] }, { kind: 'num', id: 'b', prompt: 'New choice, I = 240 and py = 15', answers: [{ label: 'x', value: 30 }, { label: 'y', value: 8 }, { label: 'U', value: 240 }], explain: 'x = 120/4 = 30, y = 120/15 = 8. Nominal income did not change.', tags: ['consumer'] }, { kind: 'num', id: 'c', prompt: 'Income needed to buy the old bundle after the price rise', answers: [{ label: 'Income', value: 270 }], explain: '4×30 + 15×10 = 270. This compensation is 30, not the utility difference.', tags: ['consumer'] }, { kind: 'text', id: 'explain', prompt: 'Explain the choice condition and why making the old bundle affordable does not force it to be chosen.', rubric: [{ id: 'per-euro', label: 'MU per euro', patterns: [/marginal utility per (euro|unit of money)|MU.*price|MRS/i] }, { id: 'budget', label: 'Budget remains binding', patterns: [/budget|income constraint/i] }, { id: 'reopt', label: 'Re-optimisation at new relative prices', patterns: [/re.?optimi|relative price|at least as well|better bundle/i] }], model: 'The interior optimum equalises marginal utility per euro while satisfying the budget. The transfer makes the old bundle feasible, but the relative prices remain different, so the consumer can re-optimise and do at least as well.', tags: ['consumer'] }], logic: ['Identifier U = xy, prix positifs et solution intérieure.', 'Égaliser MUx/px et MUy/py puis utiliser tout le budget.', 'Après le choc, maintenir I constant ; distinguer compensation du panier et utilité.'], calc: ['Initial : y/x = 4/12 ⇒ x = 3y ; 4x + 12y = 240 ⇒ x = 30, y = 10, U = 300.', 'Après : x = 120/4 = 30, y = 120/15 = 8, U = 240.', 'Ancien panier : Icomp = 4×30 + 15×10 = 270 ; transfert = 30.', 'Avec I = 270, rechoix : x = 33,75, y = 9, U = 303,75 > 300.'], graph: ['x horizontal et y vertical : intercepts initiaux 60 et 20, pente −1/3.', 'Après py = 15 : intercept x = 60 inchangé ; intercept y = 16 et pente −4/15.', 'Le budget compensé passe par l’ancien panier mais conserve la nouvelle pente.'], modelAnswer: 'Initially, MUx/px = MUy/py and the budget imply x = 30 and y = 10, so U = 300. After py rises to 15, x = 30 and y = 8, so U = 240. Nominal income remains 240; purchasing power falls. Buying the old bundle now costs 270. The transfer makes that bundle affordable but does not restore the old relative prices. The consumer can re-optimise; at income 270 the new optimum is (33.75, 9), with utility 303.75.' },
  ladder: [
    [choice('r1-a', 'MRS_RL, R horizontal, signifie…', 'L que tu es prêt à abandonner pour un R de plus, à utilité constante', 'Le ratio vient des préférences ; le sacrifice du marché vient des prix.', [['R que tu dois obligatoirement abandonner pour un L', 'Cela inverse le bien ajouté et les axes.']], 'terminology'), choice('r1-b', 'Utilité ordinale : une transformation croissante…', 'Préserve le classement des paniers', 'Elle change les nombres sans changer l’ordre.', [['Préserve obligatoirement chaque différence numérique', 'Les écarts ne portent pas de signification cardinale.']], 'terminology')],
    [choice('r2-a', 'Pourquoi égaliser MU/prix à un optimum intérieur ?', 'Sinon un transfert de dépense améliore l’utilité', 'Le budget peut rester constant pendant la réallocation.', [['Parce que les deux quantités doivent être égales', 'Les prix et préférences peuvent justifier des quantités différentes.']]), choice('r2-b', 'Le prix d’un bien augmente, I est fixe. Ce qui diminue est…', 'Le pouvoir d’achat, pas nécessairement le revenu nominal', 'Une même somme achète moins.', [['Le revenu nominal par définition', 'Le revenu nominal est le montant d’argent I, donné inchangé.']])],
    [num('r3-a', 'U = xy, I = 100, px = 5, py = 10. Trouve x*.', 10, 'La dépense sur x vaut 50 : x = 50/5 = 10.', 'x'), num('r3-b', 'U = min(x,y), I = 48, px = 3, py = 5. Trouve x* = y*.', 6, 'Une paire coûte 8 ; 48/8 = 6.', 'paires')],
    [choice('r4-a', 'U = 3x + y et px = py = 1. Méthode et choix ?', 'Comparer MU/prix ; tout le budget sur x', 'Les substituts parfaits gardent des ratios constants ; 3 > 1.', [['Chercher nécessairement une tangence intérieure', 'Les MU ne convergent pas lorsque les quantités changent.']]), choice('r4-b', 'Rendre l’ancien panier accessible après un choc garantit…', 'Un optimum nouveau au moins aussi bon que l’ancien panier', 'Le consommateur peut choisir ce panier ou mieux.', [['Une satisfaction strictement supérieure dans tous les cas', 'La stricte amélioration demande plus de conditions ; les coins peuvent donner égalité.']])],
    [{ kind: 'text', id: 'r5-a', q: 'EN : explain the difference between willingness to trade and the market trade-off.', dim: 'english', tags: [], lang: 'en', rubric: [{ id: 'mrs', label: 'MRS from preferences', patterns: [/MRS|marginal rate of substitution/i] }, { id: 'prices', label: 'Relative prices', patterns: [/relative price|price ratio/i] }], model: 'The MRS describes the consumer’s willingness to trade goods at constant utility. The relative price describes the trade-off required by the market. They coincide at an interior optimum.' }, choice('r5-b', 'Choose the correct sentence.', 'A higher price can lower purchasing power while nominal income remains constant.', 'Prix et revenu nominal sont des données distinctes.', [['A price increase necessarily lowers nominal income.', 'Cela confond le montant monétaire et ce qu’il permet d’acheter.']], 'english')],
  ],
  acceptance: [{ text: 'Je vérifie le coût avant de classer les paniers accessibles.', why: ['Le panier préféré sans contrainte peut dépasser le budget.'] }, { text: 'Je définis MRS avec des axes et une unité.', why: ['Inverser les axes inverse le ratio pertinent.'] }, { text: 'Je reconstruis le dernier euro plutôt que réciter une tangence.', why: ['Je sais expliquer la déviation qui améliorerait un panier non optimal.'] }, { text: 'Je distingue intérieur, coin et coude.', why: ['Je reconnais les substituts et compléments parfaits.'] }, { text: 'Je sépare revenu nominal, pouvoir d’achat et substitution.', why: ['La compensation ne restaure pas automatiquement le prix relatif.'] }, { text: 'Je ne traite pas U comme une quantité de bonheur.', why: ['Le classement est ordinal ; un ratio numérique ne mesure pas le bien-être relatif.'] }],
});

const elasticityGraph: LessonDiagramSpec = {
  kind: 'curves', title: 'Même droite, sensibilités différentes', xLabel: 'Q, unités', yLabel: 'p, € par unité', xMax: 12, yMax: 12, refs: ['5'],
  note: 'Exemple pédagogique Q = 12 − p. La pente directe dQ/dp = −1 est constante, mais ε = −p/Q varie : −0,5 à (8,4), −1 à (6,6), −2 à (4,8).',
  curves: [{ label: 'Demande : p = 12 − Q', color: 'buyer', points: [[0, 12], [12, 0]], explain: 'Perdre une unité pour 1 € de hausse ne représente pas le même pourcentage à tous les points.' }],
  markers: [{ x: 8, y: 4, label: 'ε = −0,5 ; R = 32' }, { x: 6, y: 6, label: 'ε = −1 ; R = 36' }, { x: 4, y: 8, label: 'ε = −2 ; R = 32' }], initial: 6,
};
const revenueBars: LessonDiagramSpec = {
  kind: 'bars', title: 'Le prix monte ; la recette ne monte pas toujours', unit: '€ de recette', refs: ['5'],
  note: 'Même demande construite Q = 12 − p. Recette = pQ ; ce sont des recettes, pas des profits, car aucun coût n’est encore donné.',
  items: [{ label: 'p = 4 ; Q = 8', value: 32, color: 'buyer', explain: 'R = 4×8 = 32 ; demande localement inélastique.' }, { label: 'p = 6 ; Q = 6', value: 36, color: 'planner', explain: 'R = 6×6 = 36 ; élasticité unitaire, sommet de R pour cette droite.' }, { label: 'p = 8 ; Q = 4', value: 32, color: 'producer', explain: 'R = 8×4 = 32 ; demande localement élastique.' }],
};
const ELASTICITY = guidedLesson({
  id: 'elasticity-guided', topic: 'elasticity', node: 'elasticity', title: 'Élasticités — combien réagit-on, en pourcentages ?', mechanism: 'Réaction proportionnelle, signes et horizon', teaser: 'Une hausse de prix peut faire monter ou baisser la recette. Tu vas apprendre à mesurer la réaction des acheteurs, garder les bons signes et reconnaître quand une approximation ne suffit plus.',
  actors: actors({ buyer: ['Les conducteurs', 'choisissent leur consommation d’essence', 'adapter leurs trajets et dépenses aux prix'], producer: ['Le vendeur', 'observe la réaction de ses ventes', 'comprendre sa recette sans la confondre avec son profit'], gov: ['L’autorité', 'envisage un objectif de réduction d’essence', 'prévoir la hausse de prix nécessaire et ses limites'], planner: ['Toi, analyste', 'compares des réactions en pourcentages', 'garder le signe, les bases et le modèle cohérents'] }),
  blocks: [
    { id: 'scene', title: 'Même hausse de prix, pas la même liberté de réagir', human: 'Le prix de l’essence monte demain. Tu peux éviter un trajet, mais tu ne peux pas changer instantanément de voiture ou de logement. Sur plusieurs années, davantage d’options deviennent possibles : mesurer la réaction demande de préciser l’horizon.', economist: 'L’élasticité mesure une sensibilité proportionnelle de quantité à un déterminant. Elle dépend du point, du marché et de l’horizon ; ce n’est pas un trait immuable du produit.', exam: 'Elasticity measures the percentage response of quantity to a one-percent change in a determinant.', why: ['Un même changement en litres ne signifie pas la même adaptation pour un petit et un gros consommateur.', 'Une mesure en pourcentage rapporte la variation à la consommation de départ.', 'Les possibilités de substitution évoluent avec le temps, donc la réponse de quantité peut s’amplifier.'], example: 'A2 donne εSR = −0,25 et εLR = −0,60 pour l’essence. Pour un prix +5 %, l’approximation donne Q −1,25 % à court terme et −3 % à long terme.', me: 'Demain tu peux prendre moins de trajets ; l’année prochaine tu peux choisir une voiture plus sobre. Le modèle doit savoir de quelle décision on parle.', refs: ['5', '15:A2#2.1'], provenance: 'doc', checks: [choice('horizon', 'Pourquoi l’essence peut-elle être plus élastique à long terme ?', 'Davantage de possibilités de substitution deviennent accessibles', 'Véhicule, logement ou organisation des trajets peuvent changer.', [['Parce qu’une élasticité négative devient obligatoirement positive avec le temps', 'Le signe reste celui de la réaction prix-quantité ; c’est souvent la magnitude qui augmente.']])] },
    { id: 'percent', title: 'Avant le sigle : comparer deux pourcentages', human: 'Si les ventes passent de six à quatre, tu as perdu deux unités. Mais deux sur six représentent un tiers, pas deux pour cent. Le prix qui passe de un à deux a augmenté de cent pour cent : compare les variations proportionnelles, pas les nombres bruts.', economist: 'Convention base initiale : ΔQ/Q0 et Δp/p0. L’élasticité discrète est leur ratio ; la convention doit rester identique dans les deux pourcentages.', exam: 'Using initial values, elasticity is (ΔQ/Q0)/(Δp/p0).', why: ['Une variation absolue dépend des unités choisies : litres ou millilitres donnent des nombres différents.', 'Une variation en pourcentage divise par la valeur initiale et retire ce problème d’échelle.', 'Les signes décrivent le sens : quantité en baisse et prix en hausse donnent un ratio négatif.'], example: 'L4 : Q : 6 → 4 et p : 1 → 2. ΔQ/Q0 = −2/6 = −1/3 ; Δp/p0 = 1/1 = 1 ; ε = −1/3 ≈ −0,333.', me: 'Tu écris d’abord « deux unités perdues sur les six de départ », puis tu le compares au prix qui double.', refs: ['5'], provenance: 'recalc', checks: [num('discrete', 'Q : 6 → 4, p : 1 → 2. Avec bases initiales, quelle élasticité ?', -1 / 3, '(−2/6)/(1/1) = −1/3. Le signe négatif est nécessaire.', '', [{ value: -2, feedback: '−2/1 est un ratio de variations absolues. Il manque les bases Q0 et p0.' }, { value: 1 / 3, feedback: 'La quantité baisse lorsque le prix monte : garde le signe négatif.' }])] },
    { id: 'formula', title: 'Gagne la formule locale avec les unités', human: 'Une dérivée te dit combien d’unités de vente tu perds pour un euro supplémentaire. Ce n’est pas encore un pourcentage. Multiplier par le prix de départ et diviser par la quantité de départ transforme cette réaction en pourcentage de quantité par pourcentage de prix.', economist: 'Élasticité ponctuelle de demande : εD = (dQ/dp)·(p/Q). Elle est sans unité. Pour plusieurs déterminants, utiliser la dérivée partielle appropriée.', exam: 'Point price elasticity is εD = (dQ/dp)(p/Q).', reveal: { q: 'dQ/dp est en unités par euro. Quel facteur la convertit en sensibilité proportionnelle sans unité ?', options: [{ text: 'p/Q', correct: true, feedback: '(unités/€) × (€/unité) : les unités se simplifient.' }, { text: 'Q/p', feedback: 'Les unités ne se simplifient pas ; tu obtiens l’inverse du facteur requis.' }, { text: 'p × Q', feedback: 'Cela ne normalise pas les variations par les niveaux.' }], formula: 'εD = (dQ/dp) × (p/Q) = (dQ/Q)/(dp/p)', tags: ['elasticity'] }, why: ['dQ/dp indique une réaction absolue à une petite hausse de prix.', 'dQ/Q mesure la réaction relativement à la quantité ; dp/p relativement au prix.', 'Leur ratio est comparable entre unités différentes, à condition de définir le marché et le point.'], example: 'Demande construite Q = 12 − p : dQ/dp = −1. Au point p = 4, Q = 8, ε = −1×4/8 = −0,5.', me: 'Tu convertis « une vente perdue par euro » en « combien de pourcent de ventes pour un pourcent de prix ».', diagram: elasticityGraph, refs: ['5', '20.2'], provenance: 'peda', checks: [{ kind: 'build', id: 'build-epsilon', q: 'Reconstruis l’élasticité ponctuelle de Q par rapport à p.', lhs: 'εD', tokens: ['dQ/dp', '×', 'p/Q', 'Q/p', '+'], accept: [['dQ/dp', '×', 'p/Q']], dim: 'formula', tags: [], explain: 'La dérivée absolue est normalisée par p/Q.' }, num('point', 'Q = 12 − p. Quelle εD à p = 4 ?', -0.5, 'Q = 8 et dQ/dp = −1, donc εD = −4/8 = −0,5.')] },
    { id: 'inverse', title: 'Ne dérive pas la fonction dans le mauvais sens', human: 'Un énoncé te donne parfois le prix en fonction de la quantité. Sa pente répond alors « combien d’euros par unité », tandis que l’élasticité de demande demande « combien d’unités par euro ». Réécris la demande ou inverse correctement la dérivée avant de calculer.', economist: 'Si p = A − BQ, alors Q = (A − p)/B, dQ/dp = −1/B et εD = −p/(BQ).', exam: 'For inverse demand p = A − BQ, price elasticity is −p/(BQ), not −B·p/Q.', why: ['Les axes d’un graphique usuel montrent p(Q), mais la réponse recherchée est Q(p).', 'dp/dQ et dQ/dp sont réciproques lorsque la relation est localement inversible.', 'Oublier cette inversion donne un résultat faux tout en conservant parfois un signe plausible.'], example: 'Situation différente : p = 20 − 2Q. À Q = 5, p = 10. dQ/dp = −1/2 ; ε = −(1/2)×10/5 = −1, et non −4.', me: 'Si tu vois la pente −2 sur la copie, demande « deux quoi par quoi ? ». Cette question suffit souvent à repérer l’inversion.', refs: ['2.4', '5', '20.2'], provenance: 'peda', checks: [num('inverse', 'p = 20 − 2Q, Q = 5, p = 10. Quelle εD ?', -1, 'dQ/dp = −1/2 ; (−1/2)×10/5 = −1.', '', [{ value: -4, feedback: 'Tu as employé dp/dQ = −2 à la place de dQ/dp = −1/2.' }])] },
    { id: 'linear', title: 'La pente ne bouge pas, l’élasticité oui', human: 'Sur Q = 12 − p, chaque euro supplémentaire fait perdre une unité partout. Mais une unité perdue pèse peu quand tu en vends beaucoup et beaucoup quand tu en vends peu. La droite est inchangée ; la réaction proportionnelle dépend du point.', economist: 'Demande linéaire Q = a − bp : pente directe −b constante, ε = −bp/(a − bp) variable. Inélastique : |ε| < 1 ; élastique : |ε| > 1.', exam: 'A linear demand curve has constant slope but variable elasticity.', why: ['La dérivée mesure la variation absolue et reste constante sur cette droite.', 'Le facteur p/Q change quand tu te déplaces sur la courbe.', 'À prix élevé et petite Q, une perte donnée représente un pourcentage plus grand de Q et un pourcentage plus petit du prix.'], example: 'Même Q = 12 − p : à p = 4, Q = 8 et ε = −0,5 ; à p = 6, Q = 6 et ε = −1 ; à p = 8, Q = 4 et ε = −2.', me: 'Perdre une vente sur huit est moins lourd que perdre une vente sur quatre, même si les deux pertes viennent d’un euro de hausse.', diagram: elasticityGraph, refs: ['5'], provenance: 'peda', checks: [num('high-point', 'Q = 12 − p : calcule εD à p = 8.', -2, 'Q = 4 ; εD = −1×8/4 = −2.'), choice('classification', 'εD = −2 décrit une demande…', 'Élastique', 'La réaction proportionnelle en valeur absolue dépasse 1.', [['Inélastique parce que −2 est inférieur à −1', 'On compare |ε| à 1 ; le signe négatif décrit le sens, pas la faible magnitude.']], 'terminology')] },
    { id: 'revenue', title: 'Le vendeur gagne plus par unité, mais vend moins', human: 'Une hausse de prix a deux effets sur la recette : chaque unité vendue rapporte davantage, mais certaines ventes disparaissent. Si les acheteurs réagissent peu, le premier effet domine. S’ils réagissent beaucoup, la perte de ventes domine.', economist: 'R = pQ(p), donc dR/dp = Q + p·dQ/dp = Q(1 + εD). Inélastique : hausse de p accroît R localement ; élastique : elle réduit R.', exam: 'A price rise increases revenue when demand is inelastic and decreases it when demand is elastic.', reveal: { q: 'R = pQ(p). Quand p change, quelle expression compte les deux effets ?', options: [{ text: 'Q + p·dQ/dp', correct: true, feedback: 'Q vient du prix accru sur les ventes ; p·dQ/dp vient du changement de ventes.' }, { text: 'Q seulement', feedback: 'Tu oublies que les acheteurs changent leur quantité.' }, { text: 'p·dQ/dp seulement', feedback: 'Tu oublies le supplément reçu sur les unités conservées.' }], formula: 'dR/dp = Q + p(dQ/dp) = Q[1 + (dQ/dp)(p/Q)] = Q(1 + εD)', tags: ['elasticity'] }, why: ['Les deux composantes de pQ varient ; il faut la règle du produit.', 'Le signe de 1 + εD indique quel effet domine lorsque Q > 0.', 'Cette conclusion concerne une petite variation locale ; pour une grande variation, calcule directement les deux recettes.'], example: 'Pour Q = 12 − p : à p = 4, R = 32 ; à p = 5, Q = 7, R = 35. À p = 8, R = 32 ; à p = 9, Q = 3, R = 27.', me: 'Tu vends une place plus cher. N’oublie pas les étudiants qui quittent la file : la nouvelle étiquette n’est pas toute ta recette.', diagram: revenueBars, refs: ['5'], provenance: 'peda', checks: [choice('revenue-sign', 'εD = −0,4. Une petite hausse de p fait quoi à R ?', 'R augmente', '1 + ε = 0,6 > 0 : la quantité baisse proportionnellement moins que le prix n’augmente.', [['R baisse parce que Q baisse', 'Tu oublies le prix reçu sur les unités qui restent vendues.']]), num('revenue-level', 'Q = 12 − p : quelle recette à p = 6 ?', 36, 'Q = 6, donc R = 6×6 = 36.', '€')] },
    { id: 'profit', title: 'Recette maximale ne veut pas dire profit maximal', human: 'Le vendeur ne garde pas toute sa recette : il paie aussi pour produire. Le prix qui maximise pQ peut donc conduire à produire des unités qui coûtent trop cher. L’élasticité explique une partie du choix ; pour le profit il faut encore les coûts.', economist: 'Profit π = R − C. R maximale implique MR = 0 à l’intérieur ; profit maximal implique MR = MC avec les autres vérifications.', exam: 'Revenue maximisation and profit maximisation differ when marginal cost is positive.', why: ['Une vente supplémentaire peut augmenter la recette tout en coûtant davantage que ce qu’elle ajoute.', 'La maximisation de recette ignore ce coût supplémentaire.', 'Dès que MC > 0, l’arrêt pertinent pour le profit survient généralement avant le sommet de recette.'], example: 'Même demande inverse p = 12 − Q, coût construit C = 2Q. Recette maximale : Q = 6, p = 6, profit = 36 − 12 = 24. Profit maximal : MR = 12 − 2Q = 2 ⇒ Q = 5, p = 7, profit = 35 − 10 = 25.', me: 'Tu ne cherches pas seulement combien rentre dans la caisse ; tu regardes ce qu’il reste après le coût des cafés.', refs: ['5', '8.1'], provenance: 'peda', checks: [choice('profit-not-revenue', 'Une demande unitaire ε = −1 garantit-elle un profit maximal ?', 'Non, elle indique une recette localement stationnaire ; les coûts comptent pour le profit', 'Le profit compare MR au coût marginal.', [['Oui, puisque la recette est maximale', 'Cela ne serait garanti que sous des hypothèses supplémentaires sur les coûts et le domaine.']])] },
    { id: 'a2', title: 'A2 : utilise le signe et l’horizon pour prévoir', human: 'L’autorité veut savoir l’effet d’un prix d’essence plus élevé. Commence par l’horizon demandé et garde le signe négatif de la demande. Une hausse de prix multipliée par une élasticité négative donne une baisse de quantité.', economist: 'Approximation : %ΔQ ≈ ε·%Δp. Pour un objectif : %Δp ≈ %ΔQ/ε.', exam: 'Using the proportional approximation, a 5% price rise reduces quantity by 1.25% in the short run and 3% in the long run.', why: ['Le pourcentage de quantité par 1 % de prix est précisément la signification d’ε.', 'Pour une variation donnée, multiplier conserve cette logique en approximation locale.', 'Pour trouver la politique nécessaire, on inverse le calcul mais on conserve les signes.'], example: 'A2 : εSR = −0,25 ; εLR = −0,60. Prix +5 % ⇒ QSR ≈ −1,25 %, QLR ≈ −3 %. Objectif QLR −15 % ⇒ prix ≈ (−15)/(−0,60) = +25 %.', me: 'Avant de taper la calculatrice, prédis le sens : pour réduire l’essence avec une demande descendante, le prix doit monter.', refs: ['5', '15:A2#2.1'], provenance: 'recalc', checks: [num('a2-sr', 'εSR = −0,25 et prix +5 %. Quelle variation approximative de Q en % ?', -1.25, '−0,25×5 = −1,25 %. Garde la baisse de quantité.', '%'), num('a2-target', 'εLR = −0,60 ; objectif Q −15 %. Quelle hausse de prix approximative en % ?', 25, '(−15)/(−0,60) = +25 %. C’est l’approximation proportionnelle.', '%')] },
    { id: 'exact', title: 'Une grande variation révèle la limite de l’approximation', human: 'Multiplier des pourcentages est pratique près du point de départ. Pour une hausse importante, la courbure de la demande peut compter. Si l’énoncé impose une fonction à élasticité constante, elle donne une relation exacte différente : annonce la convention avant le chiffre.', economist: 'Si Q = A·p^ε, alors Q1/Q0 = (p1/p0)^ε. Donc p1/p0 = (Q1/Q0)^(1/ε). L’approximation linéaire n’est pas cette identité exacte.', exam: 'For constant-elasticity demand, use the exact power relation for large changes.', why: ['L’élasticité locale mesure une réaction infinitésimale ; appliquer une seule pente à une longue variation simplifie la trajectoire.', 'Une fonction à élasticité constante décrit toute cette trajectoire et permet un calcul exact.', 'Les deux résultats répondent à des conventions différentes ; l’un n’autorise pas à annoncer l’autre comme identité.'], example: 'A2 : cible Q1/Q0 = 0,85 et ε = −0,60. Exact si Q = A·p^−0,6 : p1/p0 = 0,85^(−1/0,6) ≈ 1,3111, soit +31,11 %. Approximation usuelle : +25 %. Écart ≈ 6,11 points de pourcentage.', me: 'Tu écris « approximation proportionnelle » ou « fonction constante exacte » avant de montrer le résultat : le correcteur peut alors voir le modèle choisi.', refs: ['5', '15:A2#2.1', '20.1'], provenance: 'recalc', checks: [choice('exact-v-approx', 'Le résultat +25 % pour la cible −15 % avec ε = −0,60 est…', 'L’approximation proportionnelle, pas le résultat exact de Q = A·p^−0,6', 'Le calcul exact de la fonction puissance donne environ +31,11 %.', [['Exact pour toute fonction où ε vaut −0,60 au départ', 'Une élasticité au point de départ ne fixe pas toute la fonction.']]), num('exact-simple', 'Demande construite Q = A/p, donc ε = −1. Pour diviser Q par deux, de combien faut-il augmenter p, exactement, en % ?', 100, 'Q1/Q0 = p0/p1 = 1/2 ⇒ p1 = 2p0 : prix +100 %, pas +50 %.', '%')] },
    { id: 'cross', title: 'Le prix qui change est celui d’un autre bien', human: 'Le prix du thé augmente et tu achètes davantage de café : cela suggère que l’un remplace l’autre. Le prix des biscuits augmente et les cafés consommés avec eux diminuent : cela suggère une complémentarité. Le signe se lit sur le déterminant réellement modifié, pas sur une règle « toute demande est négative ».', economist: 'Élasticité-prix croisée εij = (∂Qi/∂pj)·(pj/Qi). Positive : substituts ; négative : compléments, dans le modèle donné.', exam: 'A positive cross-price elasticity indicates substitutes; a negative one indicates complements.', why: ['Le prix du bien i reste donné : on mesure un déplacement de sa demande causé par un autre prix.', 'Si l’autre bien devient moins intéressant et que l’on bascule vers i, la réaction est positive.', 'Si les biens servent ensemble, renchérir l’un réduit l’usage du duo et peut réduire Qi.'], example: 'Entraînement construit : εcafé,thé = +0,4 et prix du thé +10 % ⇒ café ≈ +4 %. Avec εcafé,biscuit = −0,2 et prix des biscuits +10 % ⇒ café ≈ −2 %.', me: 'Tu peux expliquer le signe avant de calculer : « je remplace le thé » ou « je prends moins du duo ».', refs: ['5'], provenance: 'peda', checks: [num('cross', 'εcafé,thé = +0,4. Prix du thé +10 %. Variation approximative des cafés en % ?', 4, '0,4×10 = +4 %. Le café et le thé sont substituts dans cette situation.', '%'), choice('cross-sign', 'Une élasticité croisée négative indique…', 'Des compléments', 'Le prix de l’autre bien monte et la quantité du bien étudié baisse.', [['Une demande propre ordinaire, sans information sur les liens', 'L’indice du prix compte : il s’agit de pj, le prix d’un autre bien.']], 'terminology')] },
    { id: 'income', title: 'Quand ton revenu change, le signe raconte autre chose', human: 'Avec plus de revenu, tu peux acheter davantage d’un bien normal. Tu peux aussi abandonner un bien utilisé surtout quand le budget était serré : il est alors inférieur sur ce domaine de revenu. Ces termes décrivent une réaction de quantité, pas la qualité morale ou matérielle du bien.', economist: 'Élasticité-revenu η = (∂Q/∂I)·(I/Q). η < 0 : inférieur ; η > 0 : normal ; η > 1 : luxe ; 0 < η < 1 : nécessité normale.', exam: 'Income elasticity is negative for an inferior good and greater than one for a luxury.', why: ['Le revenu change les paniers accessibles alors que les prix restent constants.', 'La réponse dépend des préférences et du point de revenu observé.', 'Un même bien peut changer de catégorie quand les besoins et alternatives changent.'], example: 'Exemples construits : η = −2, revenu +10 % ⇒ Q ≈ −20 %. η = 1,4, revenu +10 % ⇒ Q ≈ +14 % : ce bien est normal et de luxe sur le domaine étudié.', me: 'Une auberge peut être ton option normale à petit revenu, puis être remplacée par un hôtel quand tes moyens augmentent. « Inférieur » décrit ce choix.', refs: ['4.5', '5'], provenance: 'peda', checks: [num('income', 'η = −2, revenu +10 %. Variation approximative de Q en % ?', -20, '−2×10 = −20 %. Le bien est inférieur dans ce domaine.', '%'), choice('luxury', 'η = 1,4 signifie…', 'Bien normal dont la quantité croît plus que proportionnellement au revenu', '1,4 > 1 : bien de luxe au sens de l’élasticité-revenu.', [['Bien de mauvaise qualité parce qu’il est cher', 'Cette classification ne juge ni la qualité ni le niveau du prix.']], 'terminology')] },
    { id: 'arc', title: 'Deux points : annonce quelle base tu utilises', human: 'Une variation de 6 à 4 ne donne pas le même pourcentage si tu prends 6, 4 ou leur moyenne comme base. Pour comparer deux points symétriquement, la méthode d’arc utilise les moyennes. Elle ne doit pas être mélangée avec une base initiale pour l’autre variable.', economist: 'Élasticité d’arc : [ΔQ/((Q0+Q1)/2)] / [Δp/((p0+p1)/2)]. Les deux dénominateurs suivent la même convention.', exam: 'Arc elasticity uses average quantity and average price as the percentage bases.', why: ['La base initiale dépend du sens dans lequel tu parcours le changement.', 'Les moyennes traitent les deux points de façon symétrique.', 'Changer la base change la mesure discrète ; préciser la convention rend le calcul interprétable.'], example: 'Q : 6 → 4, p : 1 → 2. Arc : (−2/5)/(1/1,5) = −0,4/(2/3) = −0,6. Base initiale de L4 : −1/3. Les données sont identiques ; la convention diffère.', me: 'Sur ta copie tu notes « arc, bases moyennes » et tu utilises cinq pour Q et 1,5 pour p ; tu ne mélanges pas cinq et un.', refs: ['5', '20.1'], provenance: 'peda', checks: [num('arc', 'Q : 6 → 4, p : 1 → 2. Quelle élasticité d’arc avec bases moyennes ?', -0.6, 'Moyennes : Q = 5, p = 1,5. (−2/5)/(1/1,5) = −0,6.'), choice('mixed-base', 'Utiliser Q moyen mais p initial donne…', 'Un mélange de conventions à éviter', 'Le ratio n’est ni la mesure d’arc définie, ni la mesure sur base initiale.', [['La même chose que l’arc par définition', 'L’arc prend les moyennes dans les deux pourcentages.']])] },
    { id: 'limits', title: 'Les cas limites et la dernière vérification', human: 'Si la quantité ne change jamais quand le prix bouge, la demande est parfaitement inélastique. Si un écart infinitésimal de prix fait basculer les achats dans le modèle limite, elle est parfaitement élastique. Entre les deux, garde le signe et le point : tu ne peux pas attribuer automatiquement une élasticité unique à toute une droite.', economist: 'Demande verticale : ε = 0. Demande horizontale dans le cas limite : |ε| infini. À Q = 0, ε = (dQ/dp)p/Q n’est pas définie ; examiner une limite si justifiée.', exam: 'Perfectly inelastic demand is vertical; perfectly elastic demand is horizontal in the limiting model.', why: ['Une ligne verticale fixe Q malgré le prix : dQ/dp = 0.', 'Une ligne horizontale fixe le prix admissible et permet une réaction de quantité arbitrairement forte dans le modèle idéal.', 'La division par Q impose un domaine : au point où Q est nul, ne donne pas un ratio fini sans justification.'], example: 'Demande construite Q = 12 − p : à p = 0 et Q = 12, ε = 0 au point ; cela ne rend pas la droite entière verticale. Quand p approche 12 par valeurs inférieures, Q approche 0 et |ε| devient très grand.', me: 'Tu vérifies « quel prix ? quelle quantité ? quelle variable a changé ? quelle convention ? » avant de classifier ou calculer une recette.', diagram: elasticityGraph, refs: ['5', '20.2'], provenance: 'peda', checks: [choice('vertical', 'Une demande parfaitement inélastique a une courbe…', 'Verticale, Q ne change pas lorsque p change', 'La réaction proportionnelle de Q est nulle.', [['Horizontale, car ε = 0 signifie pente horizontale', 'Tu as confondu dQ/dp et la pente dessinée dp/dQ.']], 'graph'), { kind: 'text', id: 'explain-elastic', q: 'Explique avec tes mots pourquoi la hausse de prix peut baisser la recette.', dim: 'intuition', tags: [], rubric: [{ id: 'unit', label: 'Plus par unité', patterns: [/plus.*(par unite|chaque unite)|prix.*(augment|mont)/i] }, { id: 'volume', label: 'Perte des ventes', patterns: [/quantite.*(baiss|diminu)|per(te|d).*vent|moins.*vend/i] }, { id: 'dominant', label: 'Réaction proportionnelle dominante', patterns: [/proportion|elastique|plus que|domine/i] }], model: 'Le prix plus élevé rapporte davantage sur chaque unité conservée, mais réduit les ventes. Si la demande est élastique, la baisse proportionnelle de quantité domine la hausse du prix : la recette diminue.' }] },
  ],
  chain: [{ text: 'Identifier la variable et l’horizon', because: 'Prix propre, autre prix et revenu ne décrivent pas la même réaction ; court et long terme n’offrent pas les mêmes possibilités.' }, { text: 'Transformer la réaction en pourcentages', because: 'On veut comparer la variation relativement aux niveaux de départ, pas une pente brute avec des unités.' }, { text: 'Garder le signe et le point', because: 'Le signe décrit le sens ; la magnitude peut varier le long de la même droite.' }, { text: 'Calculer sous une convention annoncée', because: 'Approximation locale, arc et fonction puissance exacte peuvent donner des chiffres différents.' }, { text: 'Revenir à la décision économique', because: 'La réaction indique substitution, type de bien, objectif de quantité ou effet sur la recette, sans remplacer un calcul de profit.' }],
  teach: { prompt: 'Une amie dit « l’essence a ε = −0,6, donc augmenter son prix de 25 % réduit exactement Q de 15 % et augmente forcément le profit ». Explique ce qui est correct, ce qui manque et comment tu raisonnerais.', links: [{ id: 'meaning', label: 'Sensibilité proportionnelle négative', explain: '1 % de prix en plus donne environ 0,6 % de Q en moins localement.', patterns: [/pourcent|%|proportion/i] }, { id: 'approx', label: '25 % est une approximation', explain: 'Une grande variation nécessite un modèle ou une convention explicite.', patterns: [/approxim|local|pas exact|31[,.]11/i] }, { id: 'revenue', label: 'Inélastique : recette locale en hausse', explain: 'Avec |ε| < 1, l’effet prix domine localement.', patterns: [/recette|revenu.*vente|revenue/i] }, { id: 'profit', label: 'Coûts pour le profit', explain: 'La recette ne suffit pas à conclure sur π.', patterns: [/co[uu]t|profit.*(pas|diff|depend)/i] }], errors: [{ mis: 'slope-is-elasticity', patterns: [/elasticite.*(egale|est).*pente.*toujours|pente.*elasticite.*identique/i], refine: 'La dérivée doit être normalisée par p/Q ; sur une droite, l’élasticité varie avec le point.' }, { mis: 'approx-is-exact', patterns: [/25.*exact|exact.*25/i], refine: '25 % est l’approximation de la cible A2. Pour Q = A·p^−0,6, la solution exacte est environ +31,11 %.' }, { mis: 'revenue-is-profit', patterns: [/recette.*(egale|est la meme).*profit/i], refine: 'Le profit retranche les coûts. Une recette supérieure ne prouve pas un profit supérieur.' }], model: 'ε = −0,6 décrit une baisse proportionnelle de Q quand p augmente, sur l’horizon et au point précisés. Le calcul −15/(−0,6) = +25 % est l’approximation proportionnelle. Si l’on impose Q = A·p^−0,6 pour tout le changement, la hausse exacte est environ 31,11 %. Une demande inélastique fait monter la recette pour une petite hausse de prix ; le profit dépend aussi des coûts, et une grande variation exige de comparer les niveaux.' },
  exam: { id: 'elasticity-guided-exam', title: 'Elasticity, revenue and a large price change', ref: '5', note: 'Entraînement construit fondé sur L4, A2.1 et les pièges §20. Les valeurs de la demande linéaire et de l’objectif exact sont des variantes pédagogiques, pas un sujet officiel.', statement: 'Demand is Q = 120 − 2p. (a) Compute point price elasticity at p = 20 and classify demand. (b) Compute revenue at p = 20 and p = 25. Explain the direction of change. (c) In a different market, demand has constant elasticity Q = A·p^−0.5. Find the exact price increase needed to reduce quantity by 20%, and compare it with the proportional approximation.', parts: [{ kind: 'num', id: 'a', prompt: 'At p = 20', answers: [{ label: 'Q', value: 80 }, { label: 'εD', value: -0.5 }], explain: 'dQ/dp = −2, Q = 80, ε = −2×20/80 = −0.5 : inelastic.', tags: ['elasticity'] }, { kind: 'num', id: 'b', prompt: 'Revenue levels', answers: [{ label: 'R at p = 20', value: 1600 }, { label: 'R at p = 25', value: 1750 }], explain: '20×80 = 1 600 ; at 25, Q = 70 and R = 1 750.', tags: ['elasticity'] }, { kind: 'num', id: 'c', prompt: 'Price increase in percent in the other market', answers: [{ label: 'Exact increase (%)', value: 56.25 }, { label: 'Approximate increase (%)', value: 40 }], explain: 'p1/p0 = 0.8^(−2) = 1.5625, exact +56.25%. Approximation: (−20)/(−0.5) = +40%.', tags: ['elasticity'] }, { kind: 'text', id: 'explain', prompt: 'Explain revenue versus profit, and why the two price targets differ.', rubric: [{ id: 'costs', label: 'Profit includes costs', patterns: [/cost|profit.*revenue/i] }, { id: 'approx', label: 'Local approximation', patterns: [/approxim|local|large change/i] }, { id: 'exact', label: 'Power relation', patterns: [/constant.elasticity|power|exact function/i] }], model: 'Demand is inelastic at the initial point, so a small price rise increases revenue. The level calculation confirms the rise from 1,600 to 1,750. Profit cannot be inferred without costs. In the other market, the exact constant-elasticity power relation differs from the local proportional approximation for a large change.', tags: ['elasticity'] }], logic: ['Identifier demande directe et calculer Q au point demandé.', 'Normaliser la dérivée par p/Q puis classifier avec |ε|.', 'Calculer R = pQ aux deux points au lieu d’extrapoler aveuglément une conclusion locale.', 'Pour le changement exact de l’autre marché, utiliser le ratio de la fonction puissance.'], calc: ['Q(20) = 80 ; ε = (−2)×20/80 = −0,5.', 'R(20) = 1 600 ; Q(25) = 70 ; R(25) = 1 750.', '0,8 = (p1/p0)^−0,5 ⇒ p1/p0 = 0,8^−2 = 1,5625 : +56,25 %.', 'Approximation = (−20)/(−0,5) = +40 %.'], graph: ['Q horizontal, p vertical : demande inverse p = 60 − 0,5Q.', 'Marquer (Q,p) = (80,20) et (70,25), puis les rectangles pQ correspondants.', 'Ne pas utiliser cette droite pour représenter l’autre marché à élasticité constante.'], modelAnswer: 'At p = 20, Q = 80 and εD = −2(20/80) = −0.5, so demand is inelastic. Revenue rises from 20×80 = 1,600 to 25×70 = 1,750; costs are needed to infer profit. In the separate constant-elasticity market, 0.8 = (p1/p0)^−0.5 implies p1/p0 = 1.5625, an exact 56.25% increase. The proportional approximation gives 40%; it is not exact for this large change.' },
  ladder: [
    [choice('r1-a', 'Une demande est élastique si…', '|εD| > 1', 'La réaction proportionnelle de Q dépasse celle du prix.', [['εD est négative, quelle que soit sa magnitude', 'La plupart des demandes descendantes ont un signe négatif ; cela ne suffit pas à classifier la magnitude.']], 'terminology'), choice('r1-b', 'Une élasticité croisée positive indique…', 'Des substituts dans le modèle donné', 'Le prix de l’autre bien augmente et la demande étudiée augmente.', [['Un bien de luxe', 'Le luxe se lit avec l’élasticité-revenu, pas croisée.']], 'terminology')],
    [choice('r2-a', 'Pourquoi normaliser la dérivée par p/Q ?', 'Pour convertir la réaction absolue en réaction proportionnelle', 'Les unités se simplifient et les niveaux du point sont pris en compte.', [['Pour rendre toutes les élasticités positives', 'La normalisation ne supprime pas le signe de la dérivée.']]), choice('r2-b', 'εD = −2, petite hausse du prix. Pourquoi R baisse-t-elle ?', 'La baisse proportionnelle des ventes domine le gain par unité', '1 + ε = −1 < 0.', [['Le prix n’apporte aucun gain sur les unités vendues', 'Ce gain existe mais est dépassé par la perte de volume.']])],
    [num('r3-a', 'Q = 30 − 2p. Calcule εD à p = 5.', -0.5, 'Q = 20 ; dQ/dp = −2 ; ε = −2×5/20 = −0,5.'), num('r3-b', 'εD = −1,5 ; prix −10 %. Variation approximative de Q en % ?', 15, '−1,5×(−10) = +15 %.', '%')],
    [num('r4-a', 'Q = A·p^−1. Pour réduire Q de 20 %, hausse exacte du prix en % ?', 25, 'Q1/Q0 = 0,8 ; p1/p0 = 1/0,8 = 1,25 : +25 %.', '%'), choice('r4-b', 'Une pente directe constante garantit-elle une élasticité constante ?', 'Non : p/Q varie le long de la courbe', 'La pente n’est qu’un facteur de ε.', [['Oui, une droite a la même sensibilité proportionnelle partout', 'Une même unité perdue n’a pas le même poids dans une grande ou petite quantité.']])],
    [choice('r5-a', 'Choose the correct revenue statement.', 'With inelastic demand, a small price increase raises revenue.', 'La réaction de quantité est proportionnellement plus faible.', [['A higher price always raises revenue and profit.', 'Les ventes peuvent réagir fortement et les coûts manquent pour le profit.']], 'english'), { kind: 'text', id: 'r5-b', q: 'EN : explain why a linear demand curve can have different elasticities at different points.', dim: 'english', tags: [], lang: 'en', rubric: [{ id: 'slope', label: 'Constant derivative', patterns: [/constant (slope|derivative)/i] }, { id: 'ratio', label: 'Changing p/Q', patterns: [/p\s*\/\s*Q|price.to.quantity|price.*quantity.*ratio/i] }], model: 'The derivative is constant, but elasticity equals the derivative multiplied by p/Q. The price-to-quantity ratio changes along the curve, so elasticity changes.' }],
  ],
  acceptance: [{ text: 'Je reconnais la variable modifiée et l’horizon.', why: ['Prix propre, prix croisé et revenu ne donnent pas la même classification.'] }, { text: 'Je retrouve ε avec la dérivée et p/Q.', why: ['Je peux justifier la formule par les pourcentages et les unités.'] }, { text: 'Je garde le signe sans confondre magnitude et ordre négatif.', why: ['Élastique se juge avec |ε| > 1.'] }, { text: 'Je distingue pente et élasticité.', why: ['Une demande linéaire n’a pas une élasticité unique.'] }, { text: 'Je précise approximation, arc ou exact.', why: ['Une grande variation peut rendre l’écart important.'] }, { text: 'Je relie l’élasticité à R sans promettre un profit.', why: ['Le profit demande les coûts et les autres conditions du problème.'] }],
});

