const firmGraph: LessonDiagramSpec = {
  kind: 'curves', title: 'Une firme : coût du suivant, coût moyen et prix reçu', xLabel: 'q, unités de la firme', yLabel: '€ par unité', xMax: 8, yMax: 22, refs: ['6.4', '6.5'],
  note: 'Exemple L6 C(q) = 10 + q². MC = 2q ; AVC = q ; ATC = 10/q + q pour q > 0. Points de ATC exacts reliés, segments visuels approximatifs. Le prix de 12 est donné à la firme ; q* = 6.',
  curves: [{ label: 'MC = 2q', color: 'producer', points: [[0, 0], [8, 16]], explain: 'Coût de l’unité marginale ; la firme le compare au prix.' }, { label: 'AVC = q', color: 'third', points: [[0, 0], [8, 8]], explain: 'Coût variable moyen : ce que la recette doit couvrir pour produire avec FC inévitable.' }, { label: 'ATC = 10/q + q', color: 'planner', points: [[0.5, 20.5], [1, 11], [2, 7], [3, 10 / 3 + 3], [Math.sqrt(10), 2 * Math.sqrt(10)], [4, 6.5], [6, 46 / 6], [8, 9.25]], explain: 'Coût total par unité ; le comparer au prix révèle profit ou perte.' }, { label: 'Prix donné p = 12', color: 'buyer', points: [[0, 12], [8, 12]], explain: 'MR = p pour cette firme price taker.' }],
  markers: [{ x: 6, y: 12, label: 'p = MC : q* = 6' }, { x: Math.sqrt(10), y: 2 * Math.sqrt(10), label: 'min ATC ≈ 6,325' }], initial: 6,
};
const shutdownGraph: LessonDiagramSpec = {
  kind: 'curves', title: 'Produire peut limiter une perte', xLabel: 'q, unités de la firme', yLabel: '€ par unité', xMax: 5, yMax: 22, refs: ['6.6'],
  note: 'Autre situation construite : C(q) = 16 + 4q + q², coût fixe de 16 inévitable. MC = 4 + 2q ; AVC = 4 + q. À p = 6, q* = 1 et perte = 15, contre 16 à l’arrêt. Le seuil standard est inf AVC = 4, atteint comme limite à q → 0.',
  curves: [{ label: 'MC = 4 + 2q', color: 'producer', points: [[0, 4], [5, 14]], explain: 'À p = 6, MC atteint p pour q = 1.' }, { label: 'AVC = 4 + q', color: 'third', points: [[0, 4], [5, 9]], explain: 'À q = 1, AVC = 5 < p : une partie du fixe est couverte.' }, { label: 'ATC = 16/q + 4 + q', color: 'planner', points: [[1, 21], [2, 14], [3, 16 / 3 + 7], [4, 12], [5, 12.2]], explain: 'p = 6 est sous ATC : le profit est négatif malgré la décision de produire.' }, { label: 'Prix p = 6', color: 'buyer', points: [[0, 6], [5, 6]], explain: 'Le prix couvre AVC à q*, mais pas ATC.' }], markers: [{ x: 1, y: 6, label: 'q* = 1, perte 15' }], initial: 1,
};
const COSTS = guidedLesson({
  id: 'costs-guided', topic: 'costs', node: 'costs', title: 'Production et coûts — faut-il produire, avec quoi, et combien ?', mechanism: 'Technologie, coût minimal et décision de la firme', teaser: 'Un travailleur supplémentaire n’ajoute pas la production moyenne. Une perte ne signifie pas toujours fermer. Tu vas reconstruire ces décisions et relier l’atelier, ses coûts et l’offre du marché.',
  actors: actors({ producer: ['Toi, responsable de l’atelier', 'choisis les inputs puis la quantité', 'produire au coût minimal et maximiser le profit économique'], buyer: ['Les clients', 'achètent au prix de marché', 'payer le même prix pour un produit homogène'], third: ['Travailleurs et propriétaires de machines', 'fournissent L et K aux prix w et r', 'être rémunérés pour leur usage et leur meilleure alternative'], planner: ['Toi, analyste', 'sépares technologie, coût et horizon', 'comparer la bonne alternative : produire, arrêter ou sortir'] }),
  blocks: [
    { id: 'scene', title: 'Avant le profit, il y a une vraie production', human: 'Tu diriges un petit atelier : des travailleurs L et des machines K produisent des unités Q. Deux questions se suivent. D’abord « avec quel mélange produire la quantité visée au moindre coût ? », puis « quelle quantité vaut la peine d’être vendue au prix du marché ? ».', economist: 'Technologie Q = f(K,L). Minimisation du coût conditionnelle à Q, puis maximisation de π(q) = pq − C(q). La quantité de firme q se distingue de la quantité totale du marché Q.', exam: 'The firm chooses a cost-minimising input mix, then a profit-maximising output quantity.', why: ['Une technologie relie les ressources physiques à l’output, avant les prix de vente.', 'Les prix des inputs transforment un mélange physique en dépense monétaire.', 'Le prix de l’output permet ensuite de comparer la recette au coût ; ce n’est pas le même problème de choix.'], example: 'Situation construite Q = √(KL) : K = 20 et L = 5 produisent Q = √100 = 10. Avec w = 4 et r = 1, ce mélange coûte 4×5 + 1×20 = 40.', me: 'Tu ne peux pas fixer une quantité rentable sans savoir quelles ressources elle exige ; tu ne peux pas minimiser les ressources en oubliant l’output à fournir.', diagram: inputGraph, refs: ['6.1', '6.2', '6.5'], provenance: 'peda', checks: [choice('two-decisions', 'Minimiser le coût pour Q = 10 signifie…', 'Choisir les inputs les moins coûteux capables de produire 10', 'L’output est imposé dans ce premier problème.', [['Choisir Q = 0 parce que cela coûte moins', 'Cela viole la quantité cible. Choisir la quantité vient dans le problème de profit.']], 'recognition')] },
    { id: 'mp', title: 'Ce qu’ajoute le dixième travailleur', human: 'Ne répartis pas toute la production sur le dernier travailleur. Son apport est seulement la différence entre ce que l’atelier produit avec lui et sans lui, les machines restant fixes. La moyenne répond à une autre question : combien produit-on par travailleur présent ?', economist: 'Produit marginal discret MPL = ΔQ/ΔL, K fixé. Produit moyen APL = Q/L. Continu : MPL = ∂Q/∂L.', exam: 'Marginal product is the additional output from an extra worker, holding capital fixed.', why: ['La décision d’embaucher concerne ce qui change avec une personne supplémentaire.', 'La production déjà possible avant l’embauche ne lui est pas attribuée.', 'Une moyenne combine tous les travailleurs ; elle ne mesure pas le gain de la prochaine embauche.'], example: 'L5 : à L = 9, Q = 50 ; à L = 10, Q = 54 ; à L = 11, Q = 56. Le dixième ajoute 4, le onzième 2. À L = 10, la moyenne est 54/10 = 5,4.', me: 'Avant d’embaucher le onzième, tu demandes « deux unités de plus valent-elles son salaire ? », pas « est-ce que 56/11 paraît grand ? ».', refs: ['6.1'], provenance: 'recalc', checks: [num('mp10', 'Q passe de 50 à 54 lorsque L passe de 9 à 10. Quel produit du dixième travailleur ?', 4, '54 − 50 = 4, K fixé.', 'unités/travailleur'), num('ap10', 'À L = 10 et Q = 54, quel produit moyen ?', 5.4, 'APL = Q/L = 54/10 = 5,4. Ce n’est pas le produit marginal 4.', 'unités/travailleur', [{ value: 4, feedback: '4 est l’apport du dixième ; la moyenne utilise toute la production 54 et les dix travailleurs.' }])] },
    { id: 'hiring', title: 'Le travailleur doit rapporter ce qu’il coûte à la marge', human: 'Un travailleur peut être productif physiquement sans être rentable au salaire demandé. Convertis son output supplémentaire en recette en multipliant par le prix de vente, puis compare au salaire. Cela suppose que ton atelier peut vendre au prix donné sans le faire varier.', economist: 'Firme price taker : valeur du produit marginal p·MPL ; embaucher tant que p·MPL > w. À l’intérieur, p·MPL = w. Avec pouvoir de marché, utiliser MR·MPL.', exam: 'A competitive firm hires labour until the value of its marginal product equals the wage.', why: ['MPL est en output par travailleur, le salaire en monnaie par travailleur : il faut une conversion.', 'Multiplier MPL par p donne la recette ajoutée si le prix de vente reste donné.', 'Continuer au-delà de p·MPL = w ferait coûter plus que ce que la dernière embauche rapporte.'], example: 'Reprends L5 avec prix construit p = 3 et salaire w = 9. Dixième : 3×4 = 12 > 9 ; onzième : 3×2 = 6 < 9. Si ces incréments décrivent les options pertinentes, le dixième vaut son coût, le onzième non.', me: 'Tu compares les neuf de salaire au chiffre d’affaires supplémentaire, pas au chiffre d’affaires total de l’atelier.', refs: ['6.1'], provenance: 'peda', checks: [num('vmpl', 'p = 3 et MPL du onzième = 2. Combien rapporte cette embauche supplémentaire ?', 6, 'p·MPL = 3×2 = 6, à comparer au salaire 9.', '€'), choice('hire', 'Avec p·MPL = 6 et w = 9, embaucher ce travailleur améliore-t-il le profit ?', 'Non : il ajoute moins de recette que de coût', 'La contribution marginale est 6 − 9 = −3.', [['Oui parce que MPL est positif', 'Positif physiquement ne signifie pas rentable au salaire donné.']])] },
    { id: 'isoquant', title: 'Produire la même chose avec un autre mélange', human: 'Tu dois fournir dix unités. Beaucoup de combinaisons machines-travail peuvent y parvenir : moins de machines peut être compensé par plus de travail. Une isoquante regroupe ces mélanges équivalents en output ; elle ne dit pas encore lequel coûte le moins.', economist: 'Isoquante : f(K,L) = Q̄. Avec L horizontal et K vertical, pente = −MPL/MPK ; MRTS_LK = MPL/MPK, capital économisé par unité de L ajoutée.', exam: 'An isoquant shows input combinations yielding the same output; MRTS measures the technical trade-off.', why: ['On fixe l’output pour comparer uniquement le mélange d’inputs.', 'Ajouter dL crée MPL·dL de production ; retirer dK en retire MPK·|dK|.', 'Maintenir Q impose MPL·dL + MPK·dK = 0, d’où le ratio de produits marginaux.'], example: 'Q = √(KL), cible 10 : KL = 100. (L,K) = (5,20) et (10,10) produisent tous deux 10. MRTS_LK = K/L : au premier point, elle vaut 4 unités de K par L.', me: 'Tu demandes à l’ingénieur combien de machines un peu plus de travail peut remplacer sans changer la livraison ; tu demandes ensuite au comptable si cela économise de l’argent.', diagram: inputGraph, refs: ['6.2'], provenance: 'peda', checks: [num('isoquant-k', 'Q = √(KL) = 10 et L = 5. Quel K faut-il ?', 20, 'KL = 100, donc K = 100/5 = 20.', 'K'), choice('mrs-mrts', 'MRTS se rapporte à…', 'Un arbitrage technique entre inputs, à output constant', 'MRS concerne les préférences d’un consommateur, à utilité constante.', [['Un arbitrage de consommation à utilité constante', 'C’est MRS. Ici les acteurs produisent et les axes sont L et K.']], 'terminology')] },
    { id: 'isocost', title: 'Le marché des inputs propose aussi une pente', human: 'Le travail coûte w et les machines r. Si tu maintiens la dépense constante, un travailleur de plus exige de retirer w/r unités de capital. L’isocoût décrit ce compromis financier ; il n’est pas une isoquante de production.', economist: 'C = wL + rK ⇒ K = C/r − (w/r)L. Avec L horizontal, la pente vaut −w/r ; les intercepts sont C/w et C/r.', exam: 'An isocost line has slope −w/r when labour is on the horizontal axis.', why: ['Les deux dépenses doivent s’additionner au même coût total.', 'Ajouter une unité de L coûte w, qu’on finance en retirant w/r unités de K.', 'Le ratio de prix des inputs vient du marché, tandis que MRTS vient de la technologie.'], example: 'C = 40, w = 4, r = 1 : K = 40 − 4L, intercepts L = 10 et K = 40. (5,20) coûte 40 ; (10,10) coûte 50 et ne se trouve pas sur cet isocoût.', me: 'Deux recettes techniques livrent autant ; tu peux désormais comparer leur facture avec les mêmes prix de ressources.', diagram: inputGraph, refs: ['6.2'], provenance: 'peda', checks: [num('isocost-slope', 'Avec L horizontal, w = 4 et r = 1, quelle pente signée pour K(L) ?', -4, 'K = C/r − (w/r)L : pente = −4/1 = −4.'), num('mix-cost', 'Combien coûte (L,K) = (10,10) si w = 4 et r = 1 ?', 50, '4×10 + 1×10 = 50.', '€')] },
    { id: 'minimise', title: 'Gagne la condition du dernier euro productif', human: 'Si un euro de travail crée plus d’output qu’un euro de machine, tu peux réorganiser un peu le mélange. Pour la même dépense, tu produis davantage ; ou pour la même livraison, tu dépenses moins. Au mélange intérieur le moins cher, aucun euro ne doit travailler mieux dans un input que dans l’autre.', economist: 'Minimisation intérieure : MPL/w = MPK/r, soit MRTS_LK = w/r. Il faut aussi f(K,L) = Q̄ et vérifier coins, technologie et non-négativité.', exam: 'At an interior cost minimum, marginal product per euro is equal across inputs.', reveal: { q: 'Quelle égalité empêche un transfert de dépense d’améliorer le mélange ?', options: [{ text: 'MPL/w = MPK/r', correct: true, feedback: 'Chaque dernier euro donne le même output marginal.' }, { text: 'MPL = MPK quel que soit le prix', feedback: 'Comparer les unités d’inputs ignore ce que coûte chacune.' }, { text: 'L = K', feedback: 'Les quantités peuvent différer selon les prix et la technologie.' }], formula: 'MPL/MPK = w/r ; pour Q = √(KL), K/L = w/r. Avec KL = Q̄² : L* = Q̄√(r/w), K* = Q̄√(w/r), C* = 2Q̄√(wr)', tags: ['costs'] }, why: ['Une réallocation de dépense préserve le coût tout en changeant l’output.', 'Si les gains marginaux par euro diffèrent, le même output est atteignable à moindre coût.', 'La condition de ratio et la cible physique sont deux relations nécessaires : la tangence seule ne donne pas le niveau des inputs.'], example: 'Q̄ = 10, w = 4, r = 1 : K = 4L et KL = 100 ⇒ 4L² = 100 ⇒ L = 5, K = 20 ; C = 40. Le mélange (10,10) fournit aussi 10 mais coûte 50.', me: 'Tu n’achètes pas le même nombre de machines et d’heures pour « équilibrer ». Tu égalises leur output supplémentaire par euro.', diagram: inputGraph, refs: ['6.2'], provenance: 'peda', result: ['Mélange le moins cher pour Q = 10', 'L = 5 ; K = 20 ; C = 40'], checks: [num('min-l', 'Q = √(KL), Q̄ = 10, w/r = 4. Quel L minimise le coût ?', 5, 'K = 4L et KL = 100 ⇒ L² = 25 ⇒ L = 5, K = 20.', 'L'), { kind: 'build', id: 'cost-tangency', q: 'Reconstruis la condition intérieure de coût minimal.', lhs: 'MRTS_LK', tokens: ['MPL', '/', 'MPK', '=', 'w', '/', 'r'], accept: [['MPL', '/', 'MPK', '=', 'w', '/', 'r']], dim: 'formula', tags: [], explain: 'Le compromis technique MPL/MPK doit égaler le compromis financier w/r.' }] },
    { id: 'wage', title: 'Le salaire augmente : garde la même livraison cible', human: 'Les travailleurs deviennent plus chers, mais le contrat demande toujours dix unités. Si la technologie permet la substitution, tu utilises relativement plus de machines. Ne fais pas seulement pivoter l’ancienne facture : le mélange optimal et le coût minimal changent aussi.', economist: 'À Q fixé, une hausse de w rend L relativement cher. Pour Q = √(KL), K/L = w/r augmente ; le nouvel isocoût minimal est plus élevé.', exam: 'A higher wage induces substitution towards capital and raises minimum cost for the fixed output target.', why: ['L’isoquante reste liée au même Q, donc elle ne se déplace pas avec le salaire.', 'La pente de l’isocoût change parce que le prix relatif des ressources change.', 'Le nouveau point tangent doit encore fournir l’output imposé ; l’augmentation d’un prix d’input ne peut pas réduire le coût minimal avec technologie et autres prix inchangés.'], example: 'Q̄ = 10, r = 1, w : 4 → 9. L* = 10/3 ≈ 3,333 ; K* = 30 ; C* = 9×(10/3) + 30 = 60, contre 40. Le mélange initial coûterait maintenant 9×5 + 20 = 65.', me: 'Le nouveau mélange à 60 coûte plus qu’avant, mais évite les cinq de dépense supplémentaire qu’aurait coûtés la conservation du vieux mélange.', diagram: wageGraph, refs: ['6.2'], provenance: 'peda', checks: [num('new-k', 'Q̄ = 10, w = 9, r = 1 pour Q = √(KL). Quel K* ?', 30, 'K* = 10√(9/1) = 30 ; L* = 10/3.', 'K'), choice('isoquant-fixed', 'Après la hausse de w, si Q̄ reste 10, quelle courbe garde-t-on ?', 'La même isoquante Q = 10', 'Le prix d’un input ne modifie pas ici la technologie ni la livraison cible.', [['Une isoquante d’output plus faible par définition', 'La firme n’a pas le droit de réduire la livraison dans ce problème conditionnel.']], 'graph')] },
    { id: 'returns', title: 'Un facteur de plus ou tous les facteurs : deux expériences', human: 'Ajouter du travail à une quantité fixe de machines peut donner des gains de plus en plus faibles. Doubler simultanément machines et travail est une autre expérience : l’atelier peut doubler sa production malgré ces produits marginaux décroissants. Ne tire pas une conclusion d’échelle d’une expérience qui garde un input fixe.', economist: 'Produit marginal décroissant : un input augmente, autres fixés. Rendements d’échelle : comparer f(tK,tL) à t·f(K,L). Économies d’échelle : le coût moyen de long terme diminue avec Q.', exam: 'Diminishing marginal product does not imply decreasing returns to scale.', why: ['Avec machines fixes, davantage de travailleurs se partagent la même capacité.', 'Quand tous les inputs augmentent, la capacité par travailleur n’est plus nécessairement réduite.', 'Les rendements concernent la technologie ; les économies concernent une fonction de coût moyen à long terme, avec prix des ressources et conditions précisés.'], example: 'Q = √(KL) : K = 4, L = 9 donnent Q = 6 ; K = 8, L = 18 donnent Q = 12 : rendements constants. Pourtant MPL = 0,5√(K/L) diminue avec L à K fixé. Pour Cobb-Douglas K^αL^β, le test d’échelle compare α + β à 1.', me: 'Ne confonds pas ajouter un cuisinier dans la même cuisine et ouvrir une cuisine deux fois plus grande avec deux fois plus de cuisiniers.', refs: ['6.1', '6.3', '20.2'], provenance: 'peda', checks: [choice('returns', 'Q = √(KL), tous les inputs doublent. Les rendements d’échelle sont…', 'Constants : Q double', '√((2K)(2L)) = 2√(KL).', [['Décroissants parce que MPL diminue à K fixé', 'Tu mélanges deux expériences : ici K double aussi.']], 'recognition'), num('scale-cobb', 'Q = K^0,3 L^0,5. Quelle somme d’exposants sert au diagnostic des rendements d’échelle ?', 0.8, '0,3 + 0,5 = 0,8 < 1 : rendements décroissants. Ce n’est pas le seul exposant du travail.')] },
    { id: 'costtable', title: 'Total, moyen, marginal : trois questions à séparer', human: 'L’atelier paie une dépense fixe plus une dépense qui dépend des unités fabriquées. Le total répond « combien tout coûte ? », le moyen « combien par unité en moyenne ? », le marginal « combien coûte une petite unité de plus ? ». Les diviser ou les dériver répond donc à des questions différentes.', economist: 'TC = FC + VC ; ATC = TC/q = AFC + AVC ; AFC = FC/q ; AVC = VC/q ; MC = dTC/dq. À q = 0, les moyennes par unité ne sont pas définies.', exam: 'Average cost divides total cost by output; marginal cost differentiates total cost with respect to output.', why: ['Le coût fixe ne varie pas avec q dans l’horizon donné.', 'Les moyennes répartissent une dépense sur les unités produites.', 'La dérivée du fixe est nulle : le coût marginal ne contient pas FC quand il est constant.'], example: 'L5 : C = 30 + q² à q = 2. TC = 34, FC = 30, VC = 4, AFC = 15, AVC = 2, ATC = 17, MC continu = 4. Vérification : 15 + 2 = 17.', me: 'La facture de 34 n’est pas le coût de la prochaine unité. Et le coût moyen 17 n’est pas non plus celui de la prochaine unité.', refs: ['6.4'], provenance: 'recalc', checks: [num('atc', 'C = 30 + q² à q = 2. Quel ATC ?', 17, 'TC = 34 ; ATC = 34/2 = 17.', '€/unité'), num('mc', 'Pour C = 30 + q², quel MC continu à q = 2 ?', 4, 'MC = dC/dq = 2q, donc 4. Le fixe 30 a une dérivée nulle.', '€/unité', [{ value: 34, feedback: '34 est le total. MC est une dérivée, pas la facture.' }, { value: 17, feedback: '17 est le moyen. La dérivée vaut 4.' }])] },
    { id: 'discrete-average', title: 'Une unité entière n’est pas une variation infinitésimale', human: 'La dérivée mesure la pente au point actuel. Produire exactement une unité entière de plus additionne le coût sur toute la transition. Si le marginal augmente entre les deux niveaux, ce coût discret dépasse la dérivée au départ.', economist: 'MC continu = C′(q). Coût discret de q à q+1 : C(q+1) − C(q). Si MC < ATC, la moyenne baisse ; si MC > ATC, elle monte.', exam: 'Continuous marginal cost and the discrete cost of one extra unit need not coincide.', why: ['Une dérivée est une limite pour une très petite variation.', 'Une différence sur une unité entière couvre plusieurs valeurs marginales.', 'Le coût du nouvel ajout tire une moyenne vers lui, comme une nouvelle note au-dessus ou au-dessous de ta moyenne.'], example: 'C = 30 + q² : C(3) − C(2) = 39 − 34 = 5, alors que C′(2) = 4. Dans l’autre exemple C = 10 + q² à q = 2, MC = 4 < ATC = 7 : ATC baisse localement.', me: 'Une note de 12 augmente une moyenne de 10, même si 12 n’est pas la meilleure note imaginable. MC joue ce rôle pour ATC.', diagram: firmGraph, refs: ['6.4'], provenance: 'peda', checks: [num('discrete-cost', 'C = 30 + q² : coût exact de passer de q = 2 à q = 3 ?', 5, 'C(3) = 39 et C(2) = 34 : différence 5, pas la dérivée 4.', '€'), choice('average-direction', 'Si MC est inférieur à ATC au point considéré, ATC…', 'Diminue localement', 'L’ajout marginal est moins cher que la moyenne existante.', [['Augmente parce que TC augmente', 'Un total peut augmenter pendant que sa moyenne diminue.']])] },
    { id: 'profit', title: 'Combien vendre quand le prix est donné ?', human: 'Tes clients paient douze par unité, et ton petit atelier ne change pas ce prix. Une unité de plus ajoute donc douze de recette. Tu continues tant que son coût marginal est inférieur à douze, puis tu vérifies que le candidat est meilleur que l’arrêt et respecte le domaine.', economist: 'Price taker : π(q) = pq − C(q), MR = p. Candidat intérieur : p = MC(q), sur une branche pertinente ; comparaison avec q = 0 et contraintes.', exam: 'A price-taking firm chooses output where p = MC, provided producing is optimal relative to shutdown.', reveal: { q: 'Quel point empêche une petite hausse ou baisse de q d’améliorer le profit intérieur ?', options: [{ text: 'p = MC', correct: true, feedback: 'La dernière unité rapporte autant qu’elle coûte.' }, { text: 'p = ATC', feedback: 'Cela décrit profit nul, pas nécessairement le choix de q à tout prix.' }, { text: 'R = 0', feedback: 'La recette nulle n’est pas l’objectif.' }], formula: 'π(q) = 12q − (10 + q²) ; π′ = 12 − 2q = 0 ⇒ q* = 6 ; π″ = −2 < 0 ; π(6) = 72 − 46 = 26', tags: ['costs'] }, why: ['Une unité supplémentaire ajoute p de recette parce que la firme prend p comme donné.', 'Si p > MC, la fabriquer augmente π ; si p < MC, la retirer augmente π.', 'La condition marginale ne suffit pas sans maximum, faisabilité et comparaison à l’alternative d’arrêt.'], example: 'L6 : C = 10 + q², p = 12. q = 6 ; R = 72, C = 46, π = 26. À q = 7, π = 84 − 59 = 25 : produire davantage réduit le profit.', me: 'Tu prends le prix de douze comme une information extérieure ; tu ne le lis pas sur la demande de tout le marché pour choisir une marge de monopole.', diagram: firmGraph, refs: ['6.5'], provenance: 'recalc', result: ['Quantité choisie au prix 12', 'q* = 6 ; π = 26'], checks: [num('qstar', 'C = 10 + q², p = 12. Quel q maximise le profit ?', 6, 'MC = 2q ; 12 = 2q ⇒ q = 6. Le profit 26 dépasse celui de l’arrêt −10.', 'unités'), num('profit', 'Au même choix q = 6, quelle est π ?', 26, 'R − C = 12×6 − (10 + 36) = 72 − 46 = 26.', '€')] },
    { id: 'shutdown', title: 'Perdre quinze peut être préférable à perdre seize', human: 'Le prix chute et tu fais une perte. Si une dépense fixe doit être payée même en fermant pour la journée, fermer ne la supprime pas. Produire peut encore financer une partie de cette dépense et réduire la perte : compare les deux alternatives réelles.', economist: 'Court terme, FC inévitable : produire si la meilleure quantité donne R ≥ VC, soit p ≥ AVC(q*). À égalité, indifférence ; sinon arrêt. Le critère n’est pas simplement π ≥ 0.', exam: 'A firm may produce at a loss when revenue covers variable cost and contributes to unavoidable fixed cost.', why: ['À l’arrêt, la recette et le coût variable disparaissent, mais le fixe inévitable reste.', 'Produire vaut la peine si R − VC est positif : cette contribution réduit la perte fixe.', 'Si R < VC même au meilleur choix, produire aggrave la perte ; l’arrêt devient préférable.'], example: 'Autre situation construite : C = 16 + 4q + q², FC = 16 inévitable, p = 6. MC = 4 + 2q ⇒ q = 1 ; R = 6, VC = 5, π = −15. Arrêt : π = −16. Produire évite un euro de perte.', me: 'Le loyer est déjà dû aujourd’hui. Ouvrir gagne un euro après les coûts qui dépendent de l’ouverture : tu récupères un euro de ce loyer, même si la journée reste déficitaire.', diagram: shutdownGraph, refs: ['6.6', '20.2'], provenance: 'peda', checks: [num('shutdown-profit', 'C = 16 + 4q + q², p = 6, q = 1. Quel profit en produisant ?', -15, '6 − (16 + 4 + 1) = −15.', '€'), choice('shutdown-choice', 'Avec FC = 16 inévitable, vaut-il mieux produire à perte 15 ou arrêter à perte 16 ?', 'Produire minimise la perte', 'La recette 6 couvre VC = 5 et finance un euro du fixe.', [['Arrêter car tout profit négatif est irrationnel', 'Il faut comparer à −16, pas à une alternative zéro qui n’est pas disponible.']])] },
    { id: 'fixed-sunk', title: 'Fixe ne veut pas forcément dire irrécupérable', human: 'Une dépense peut rester la même pour toutes les quantités positives et pourtant être évitée en n’ouvrant pas. Tu ne dois donc pas retirer tous les coûts fixes du raisonnement sans lire l’horizon et le contrat. Le bon test compare ce qui change vraiment entre les options.', economist: 'Fixed : ne varie pas avec q sur le domaine. Sunk ou inévitable pour la décision : ne peut pas être récupéré/évité par l’option alternative. À long terme, sortie et ajustement des inputs deviennent possibles.', exam: 'A fixed cost is not automatically sunk; shutdown decisions depend on which costs are avoidable.', why: ['« Fixe » décrit la relation au volume ; « sunk » décrit la possibilité de récupération.', 'Si fermer évite la dépense, elle fait partie du gain de fermeture et doit entrer dans la comparaison.', 'L’horizon économique est défini par les marges d’ajustement disponibles, pas par un nombre universel de mois.'], example: 'Même activité que le bloc précédent : R = 6 et VC = 5. Si les 16 sont un paiement déjà dû, produire donne −15 contre −16 à l’arrêt. Si les 16 ne sont dus qu’en ouvrant, l’arrêt donne 0 et domine la perte −15.', me: 'Avant de dire « le fixe ne compte pas », demande si tu peux annuler cette facture en choisissant l’autre option.', refs: ['6.4', '6.6'], provenance: 'peda', checks: [choice('avoidable-fixed', 'Un paiement fixe de 16 est entièrement évitable en n’ouvrant pas. Produire donnerait π = −15. Que choisir ?', 'Ne pas ouvrir : le profit de cette option vaut 0', 'Ce fixe est évitable, donc la comparaison n’est plus −15 contre −16.', [['Produire comme dans le cas du fixe inévitable', 'Tu as conservé une hypothèse que l’énoncé a changée.']]), choice('short-run-definition', 'Le court terme signifie…', 'Au moins un input reste fixé pour la décision', 'Il s’agit des possibilités d’ajustement.', [['Exactement moins d’un an pour toute entreprise', 'Aucune durée calendaire universelle ne définit l’horizon.']], 'terminology')] },
    { id: 'supply-boundaries', title: 'L’offre n’est pas toute la courbe MC sans conditions', human: 'L’égalité p = MC donne un candidat dans une situation intérieure. Un prix trop bas peut faire choisir zéro ; une capacité peut faire choisir son maximum. Si le coût marginal est constant et que chaque vente rapporte une marge positive, il n’existe même pas de quantité optimale finie sans limite supplémentaire.', economist: 'Offre individuelle : partie pertinente de MC croissante au-dessus du seuil d’arrêt, avec contraintes. Vérifier non-négativité, capacité, maximum et coûts évitables.', exam: 'The supply rule p = MC applies with shutdown and capacity conditions, not as an unconditional equation.', why: ['Une FOC intérieure n’est pas requise à un bord du choix.', 'Avec une marge constante positive, chaque unité supplémentaire améliore encore π.', 'Une capacité ferme ce choix non borné ; un prix inférieur au coût variable peut faire préférer zéro.'], example: 'C = 5q, p = 10, capacité q ≤ 10 : π = 5q, donc q* = 10. Sans capacité ni autre coût croissant, π augmente sans borne : l’équation 10 = 5 n’a pas de solution et aucun optimum fini n’est donné.', me: 'Si chaque T-shirt rapporte cinq de marge, tu n’arrêtes pas arbitrairement à six T-shirts : tu cherches ce qui limite vraiment la production.', refs: ['6.5', '6.6', '20.2'], provenance: 'peda', checks: [num('capacity', 'C = 5q, p = 10, 0 ≤ q ≤ 10. Quel q optimal ?', 10, 'π = 5q augmente sur tout le domaine : le maximum est au bord q = 10.', 'unités'), choice('unbounded', 'Même cas sans capacité et sans coût supplémentaire croissant : que conclure ?', 'Aucun optimum fini n’est fourni par ce modèle', 'Chaque unité ajoute cinq de profit ; une limite supplémentaire est nécessaire.', [['q = 5 car MC = 5', 'Le chiffre 5 est un coût par unité, pas une quantité optimale.']], 'recognition')] },
    { id: 'market-supply', title: 'De ton atelier à tous les ateliers', human: 'Le marché additionne les unités que chaque firme offre au même prix. Une firme dont le prix ne couvre pas son seuil ne contribue pas une quantité négative : elle produit zéro. L’entrée d’une nouvelle firme change le nombre de plans additionnés et déplace l’offre de marché.', economist: 'QS(p) = Σ qi(p), en respectant chaque seuil. L6 : q1 = max(0,p − 2), q2 = max(0,p − 4). Offre par morceaux.', exam: 'Market supply is the horizontal sum of non-negative firm supplies at each price.', why: ['Les firmes reçoivent un même prix dans le modèle homogène concurrentiel.', 'Les quantités s’ajoutent, pas les prix ni les coûts marginaux verticaux.', 'Au passage d’un seuil de participation, une firme supplémentaire commence à contribuer : la relation de marché peut avoir un coude.'], example: 'L6 : à p = 3, q1 = 1 et q2 = 0, donc QS = 1. À p = 5, q1 = 3 et q2 = 1, donc QS = 4. Pour p ≥ 4, QS = 2p − 6 ; on ne peut pas utiliser ce segment à p = 3.', me: 'L’atelier voisin ferme temporairement à ce prix. Son absence réduit l’offre ; elle ne soustrait pas des unités déjà fabriquées par toi.', refs: ['6.7'], provenance: 'recalc', checks: [num('market-supply', 'q1 = max(0,p − 2), q2 = max(0,p − 4). Quel QS à p = 3 ?', 1, 'q1 = 1 et q2 = 0 ; QS = 1. Le segment 2p − 6 n’est pas valable ici.', 'unités'), num('market-supply-high', 'Même marché, quel QS à p = 5 ?', 4, 'q1 = 3 et q2 = 1, donc QS = 4.', 'unités')] },
    { id: 'entry-economic', title: 'Profit nul ne signifie pas travailler pour rien', human: 'Une demande plus forte peut faire monter prix et profits à court terme. Si de nouveaux ateliers identiques peuvent entrer facilement, leurs unités déplacent l’offre et réduisent ensuite le prix. Dans le modèle de libre entrée à coûts constants, le profit économique finit nul parce que les facteurs sont déjà rémunérés à leur coût d’opportunité.', economist: 'Cas usuel de firmes identiques réplicables : pLR = min ATC, profit économique nul, davantage de firmes pour une demande plus forte. Le coût économique inclut la meilleure alternative sacrifiée ; PS = R − VC = π + FC quand FC est inévitable.', exam: 'Zero economic profit includes the opportunity cost of all inputs; it does not imply zero income.', why: ['Un profit économique positif attire des ressources tant que l’entrée reste accessible.', 'L’offre accrue réduit le prix et l’avantage d’entrée.', 'Rémunérer ton travail à son alternative est déjà un coût économique ; nul après ce coût n’est pas un revenu nul. Le résultat d’entrée change si ressources rares, barrières ou coûts sectoriels changent.'], example: 'L6 Naomi : fournitures 30 000 + livraison 10 000 donnent coût comptable 40 000 ; salaire alternatif 50 000 donne coût économique 90 000. Avec recette construite 90 000 : profit comptable 50 000 et économique 0. Autre exemple L6 C = 10 + q² à p = 12 : PS = 72 − 36 = 36, mais π = 26.', me: 'Tu gagnes cinquante mille dans ton activité mais renonces à un emploi qui rapportait la même somme : tu n’as pas un gain économique de cinquante mille sur cette alternative.', diagram: firmGraph, refs: ['6.5', '6.7', '20.2'], provenance: 'peda', checks: [num('economic-cost', 'Dépenses explicites 40 000, salaire sacrifié 50 000. Quel coût économique sans double comptage ?', 90000, '40 000 + 50 000 = 90 000 ; l’usage de ton temps a une alternative.', '€'), choice('zero-profit', 'Profit économique nul dans le modèle de libre entrée signifie…', 'Les facteurs reçoivent déjà leur rémunération d’opportunité', 'La recette couvre les coûts explicites et implicites pertinents.', [['Les propriétaires et travailleurs ne gagnent aucun revenu', 'Leur rémunération d’opportunité est déjà incluse dans les coûts.']]), num('ps', 'C = 10 + q², q = 6, p = 12. Quel surplus du producteur R − VC ?', 36, '72 − 36 = 36 ; il diffère du profit 26 par FC = 10.', '€')] },
  ],
  chain: [{ text: 'Définir technologie et output cible', because: 'Les inputs doivent réellement permettre de produire ce qui est demandé.' }, { text: 'Égaliser la productivité marginale par euro si l’intérieur le permet', because: 'Un mélange non équilibré permet une économie de coût pour le même output.' }, { text: 'Construire total, moyen et marginal sans les confondre', because: 'La facture, le coût par unité et le coût du suivant répondent à trois questions différentes.' }, { text: 'Comparer recette marginale et coût marginal avec les contraintes', because: 'La firme choisit q, mais une capacité ou un arrêt peut rendre l’optimum non intérieur.' }, { text: 'Comparer produire, arrêter et sortir sur le bon horizon', because: 'Les coûts réellement évitables et l’alternative d’opportunité déterminent la décision.' }, { text: 'Additionner les offres et penser à l’entrée', because: 'Un résultat d’une firme à court terme ne décrit pas automatiquement le marché à long terme.' }],
  teach: { prompt: 'Ton ami veut fermer toute firme qui fait une perte et affirme que MPL décroissant veut dire rendements d’échelle décroissants. Corrige les deux idées avec des nombres et explique ce que serait la bonne décision d’une firme price taker.', links: [{ id: 'mp', label: 'Un input fixe contre tous les inputs', explain: 'Le produit marginal et les rendements d’échelle font varier des choses différentes.', patterns: [/fix[ee].*(capital|K|input)|tous.*inputs|facteurs.*(tous|ensemble)|doubl/i] }, { id: 'marginal', label: 'p = MC pour un candidat intérieur', explain: 'Le suivant rapporte p et coûte MC, sous les conditions du modèle.', patterns: [/p\s*=\s*MC|prix.*co[uu]t marginal|recette marginale/i] }, { id: 'shutdown', label: 'Comparer R à VC si FC inévitable', explain: 'Produire peut couvrir une partie du fixe et limiter la perte.', patterns: [/variable|AVC|R.*VC|partie.*fixe/i] }, { id: 'alternative', label: 'Comparer les pertes disponibles', explain: '−15 peut dominer −16 ; zéro n’est pas toujours une option.', patterns: [/15.*16|16.*15|inevitable|evitable|alternative|opportunite/i] }], errors: [{ mis: 'loss-means-shutdown', patterns: [/toujours.*arr[ee]t.*perte|perte.*toujours.*ferm/i], refine: 'Une perte ne suffit pas : si le fixe est inévitable, compare produire à la perte fixe de l’arrêt.' }, { mis: 'mp-means-returns', patterns: [/marginal.*decroiss.*implique.*echelle.*decroiss/i], refine: 'Le premier test garde d’autres inputs fixes ; le second multiplie tous les inputs.' }, { mis: 'fixed-is-sunk', patterns: [/fixe.*toujours.*(sunk|irrecuperable|inevitable)/i], refine: 'Fixe signifie indépendant du volume ; regarde séparément s’il est évitable dans l’alternative.' }], model: 'MPL décroissant mesure l’effet de plus de travail avec le capital fixé. Les rendements d’échelle augmentent tous les inputs : Q = √(KL) a des MPL décroissants mais double Q quand K et L doublent. Une firme price taker cherche un candidat p = MC puis vérifie contraintes et arrêt. Avec C = 16 + 4q + q², p = 6 et fixe inévitable, q = 1 donne R = 6, VC = 5 et perte 15. Arrêter coûte 16 : produire limite la perte. Si le fixe était évitable, l’arrêt à profit zéro serait préférable.' },
  exam: { id: 'costs-guided-exam', title: 'A competitive firm: profit, shutdown and entry', ref: '6.5', note: 'Entraînement construit d’après L5–L6 et les formats des finals E2020 Q5/E2025 Q5. La fonction de coût est une variante pédagogique ; correction recalculée, non officielle.', statement: 'A price-taking firm has short-run cost C(q) = 20 + 4q + q² for q > 0. The fixed cost of 20 is unavoidable in the short run, including when q = 0. (a) At price p = 14, find optimal output, profit and producer surplus. (b) At p = 8, find optimal output and compare producing with shutting down. (c) If identical firms can freely enter and all inputs can adjust, explain the standard long-run benchmark under a replicable constant-cost industry, using this cost function as the long-run cost schedule.', parts: [{ kind: 'num', id: 'a', prompt: 'At p = 14', answers: [{ label: 'q', value: 5 }, { label: 'Profit', value: 5 }, { label: 'Producer surplus', value: 25 }], explain: 'MC = 4 + 2q = 14 ⇒ q = 5. R = 70, VC = 45, C = 65. Profit = 5, PS = 25.', tags: ['costs'] }, { kind: 'num', id: 'b', prompt: 'At p = 8', answers: [{ label: 'q', value: 2 }, { label: 'Profit from production', value: -16 }, { label: 'Profit from shutdown', value: -20 }], explain: 'q = 2, R = 16, VC = 12, C = 32. Producing loses 16 rather than 20; contribution R − VC = 4.', tags: ['costs'] }, { kind: 'num', id: 'c-num', prompt: 'Long-run efficient scale and price under the stated benchmark', answers: [{ label: 'qLR', value: Math.sqrt(20), tol: 0.02 }, { label: 'pLR', value: 4 + 2 * Math.sqrt(20), tol: 0.02 }], explain: 'ATC = 20/q + 4 + q. Its minimum is at q = √20 ≈ 4.472 and p = 4 + 2√20 ≈ 12.944.', tags: ['costs'] }, { kind: 'text', id: 'explain', prompt: 'Explain why a loss does not force short-run shutdown and why zero economic profit does not mean zero income.', rubric: [{ id: 'avoidable', label: 'Unavoidable fixed cost', patterns: [/unavoidable|fixed cost.*(remain|paid)|sunk/i] }, { id: 'vc', label: 'Revenue covers VC', patterns: [/variable cost|AVC|contribut/i] }, { id: 'opp', label: 'Opportunity costs included', patterns: [/opportunity cost|normal return|factor remuneration/i] }], model: 'In the short run the fixed cost remains payable at shutdown. Producing at p = 8 covers variable cost and contributes 4 towards the fixed cost, reducing the loss. In the stated long-run free-entry benchmark, price falls to minimum average cost and economic profit is zero. This includes opportunity costs, so inputs still receive their normal remuneration.', tags: ['costs'] }], logic: ['Distinguer fixe inévitable et variable ; écrire MC.', 'Trouver q avec p = MC, vérifier maximum et non-négativité.', 'Calculer R, VC, C, π et PS sans les confondre.', 'Comparer les niveaux de profit avec l’arrêt, puis appliquer le benchmark de long terme seulement sous ses hypothèses.'], calc: ['MC = 4 + 2q ; π″ = −2 < 0.', 'p = 14 ⇒ q = 5 ; R = 70, VC = 45, C = 65, π = 5, PS = 25.', 'p = 8 ⇒ q = 2 ; R = 16, VC = 12, C = 32, π = −16 > −20 à l’arrêt.', 'ATC = 20/q + 4 + q ; dérivée = −20/q² + 1 = 0 ⇒ qLR = √20.', 'pLR = ATC(qLR) = 4 + 2√20 ≈ 12,944 ; profit économique nul.'], graph: ['q horizontal et monnaie par unité verticale : MC = 4 + 2q, AVC = 4 + q, ATC = 20/q + 4 + q.', 'À p = 14, q = 5 et profit rectangle (p − ATC)q = 5.', 'À p = 8, q = 2 et p est entre AVC = 6 et ATC = 16 : perte 16 mais contribution variable positive.', 'Le minimum de ATC marque le benchmark d’entrée à long terme ; ce n’est pas le seuil d’arrêt court terme.'], modelAnswer: 'At p = 14, MC = 4 + 2q gives q = 5. Revenue is 70, total cost is 65, profit is 5 and producer surplus is 25. At p = 8, q = 2, revenue is 16 and variable cost is 12. Production yields a loss of 16, compared with 20 at shutdown, so producing is optimal in the short run. Under the stated replicable free-entry benchmark, long-run price equals minimum ATC: q = √20 and p = 4 + 2√20. Zero economic profit includes opportunity costs and does not imply zero factor income.' },
  ladder: [
    [choice('r1-a', 'MPL et APL désignent…', 'Output supplémentaire du travailleur marginal ; output par travailleur en moyenne', 'Différence et ratio répondent à deux questions distinctes.', [['Deux écritures de Q/L', 'Q/L est seulement le produit moyen.']], 'terminology'), choice('r1-b', 'Rendements d’échelle teste…', 'Une variation proportionnelle de tous les inputs', 'On compare f(tK,tL) à t·f(K,L).', [['Plus de L avec K fixe', 'C’est le test du produit marginal du travail.']], 'terminology')],
    [choice('r2-a', 'Pourquoi produire avec AVC < p < ATC et FC inévitable ?', 'R couvre VC et une partie de FC, limitant la perte', 'L’arrêt laisse toute la perte fixe.', [['La firme réalise forcément un profit positif', 'p < ATC signifie encore une perte.']]), { kind: 'order', id: 'r2-b', q: 'Reconstruis la réaction d’un secteur à une demande accrue, sous libre entrée à coûts constants.', dim: 'intuition', tags: [], items: ['La demande accrue fait monter le prix à court terme', 'Des profits économiques positifs attirent l’entrée', 'L’offre de marché se déplace à droite', 'Le prix revient vers min ATC et le profit économique vers zéro'] }],
    [num('r3-a', 'C = 12 + q², p = 10. Calcule q*.', 5, 'MC = 2q, donc q = p/2 = 5 ; π = 50 − 37 = 13 > −12 à l’arrêt.', 'unités'), num('r3-b', 'C = 30 + q² à q = 3. Calcule AVC.', 3, 'VC = 9 ; AVC = 9/3 = 3, sans FC.', '€/unité')],
    [num('r4-a', 'Q = √(KL), Q̄ = 12, w = 4 et r = 1. Trouve le coût minimal.', 48, 'L = 6, K = 24 ; C = 4×6 + 24 = 48. Ou C* = 2×12×√4 = 48.', '€'), choice('r4-b', 'FC augmente mais reste inévitable, p et VC inchangés. Le q intérieur choisi…', 'Ne change pas si la décision de produire reste pertinente', 'MC est inchangé ; le fixe modifie π, pas la condition marginale.', [['Augmente pour répartir le fixe sur davantage d’unités', 'Ce raisonnement de moyenne ne remplace pas le maximum de profit à prix donné.']])],
    [{ kind: 'text', id: 'r5-a', q: 'EN : explain why negative profit need not imply shutdown in the short run.', dim: 'english', tags: [], lang: 'en', rubric: [{ id: 'fixed', label: 'Unavoidable fixed cost', patterns: [/unavoidable|fixed cost.*(remain|paid)/i] }, { id: 'variable', label: 'Covering VC', patterns: [/variable cost|AVC|contribut/i] }], model: 'If fixed cost is unavoidable, shutdown still incurs that cost. Producing is preferable when revenue covers variable cost and contributes towards fixed cost, even though total profit is negative.' }, choice('r5-b', 'Choose the correct statement.', 'Diminishing marginal product can coexist with constant returns to scale.', 'Un input fixe contre tous les inputs qui augmentent : deux expériences.', [['Diminishing marginal product always means decreasing returns to scale.', 'Q = √(KL) fournit un contre-exemple.']], 'english')],
  ],
  acceptance: [{ text: 'Je distingue MP, AP, MRS et MRTS.', why: ['Je peux nommer les acteurs, les axes et ce qui reste constant.'] }, { text: 'Je minimise un coût avec technologie et prix d’inputs.', why: ['La tangence ne suffit pas sans la cible physique et les contraintes.'] }, { text: 'Je sépare produit marginal décroissant et échelle.', why: ['Je sais quelle expérience fait varier un facteur ou tous les facteurs.'] }, { text: 'Je remplis TC, FC, VC, ATC, AFC, AVC et MC.', why: ['Je ne confonds ni moyenne et marginal, ni dérivée et coût d’une unité entière.'] }, { text: 'Je justifie q avec p = MC et vérifie les bords.', why: ['Capacité, coût constant, arrêt et non-négativité peuvent changer la méthode.'] }, { text: 'Je compare arrêt et production sur les coûts évitables.', why: ['Une perte peut être la meilleure option disponible à court terme.'] }, { text: 'Je relie offre individuelle, entrée et profit économique.', why: ['Je additionne les quantités non négatives ; zéro profit inclut les coûts d’opportunité.'] }],
});

export const FOUNDATIONS_LESSONS: Lesson[] = [SD, CONSUMER, ELASTICITY, COSTS];
